INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#2','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',1,'mc','auto','원의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":2,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"원의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"꼭짓점이 없어요","correct":true},{"t":"꼭짓점이 4개 있어요","mis":"M3-2-u3-X01"},{"t":"곧은 선으로 둘러싸여 있어요","mis":"M3-2-u3-X01"},{"t":"뾰족한 곳이 있어요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「꼭짓점이 없어요」예요."],"variant_rule":{"alt":[{"stem":"원을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"굽은 선으로 되어 있어요","correct":true},{"t":"곧은 선 3개로 둘러싸여 있어요","mis":"M3-2-u3-X01"},{"t":"꼭짓점이 3개 있어요","mis":"M3-2-u3-X01"},{"t":"한쪽으로 길쭉해요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「굽은 선으로 되어 있어요」예요."],"asset":null},{"stem":"동전을 본떠 그린 원에 대해 알맞은 말은 어느 것인가요?","options":[{"t":"어느 쪽으로 보아도 똑같이 둥글어요","correct":true},{"t":"한쪽으로 길쭉해도 돼요","mis":"M3-2-u3-X01"},{"t":"뾰족한 곳이 하나 있어요","mis":"M3-2-u3-X01"},{"t":"곧은 선이 4개 있어요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「어느 쪽으로 보아도 똑같이 둥글어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#3','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C1',1,'mc','auto','원 위에 있는 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"원 위에 있는 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄱ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄷ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[35.9,31.3,"nw"],"ㄴ":[68.4,74.6,"se"],"ㄷ":[107.6,42.7,"e"]},"circle":[[[60,60],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 굽은 선 위에 놓인 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄴ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄷ":[24.8,72.8,"w"],"ㄱ":[68.4,45.4,"ne"],"ㄴ":[103.8,85.3,"se"]},"circle":[[[60,60],37.5]]}],"tag":false}},{"stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄴ만 선 위에 있어요. 점 ㄷ은 원 안, 점 ㄱ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄴ":[95.2,72.8,"e"],"ㄷ":[45.4,51.6,"nw"],"ㄱ":[42.7,107.6,"s"]},"circle":[[[60,60],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUD