INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#4','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',1,'mc','auto','누름 못과 띠종이로 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X02']::text[],true,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"누름 못과 띠종이로 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 반지름이에요."],"asset":null},{"stem":"원의 가장 안쪽에 있는 한 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#5','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'sa','auto','선분 ㅇㄱ의 길이는 2 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":2,"kind":"sa","stem":"선분 ㅇㄱ의 길이는 2 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 2 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[92.5,41.2,"ne"],"ㄴ":[27.5,41.2,"nw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[72.9,44.8],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선분 ㅇㄱ의 길이는 3 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 3 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"n"],"ㄱ":[24.8,72.8,"w"],"ㄴ":[88.7,84.1,"se"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[44.7,72.8],"3 cm"]]}],"tag":false}},{"stem":"선분 ㅇㄱ의 길이는 4 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[35.9,88.7,"sw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[50.1,42.7],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#6','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','한 원에 반지름은 몇 개 그을 수 있나요?',ARRAY['M3-2-u3-X04']::text[],true,'{"seq":6,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"한 원에 반지름은 몇 개 그을 수 있나요?","options":[{"t":"셀 수 없이 많아요","correct":true},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"},{"t":"4개","mis":"M3-2-u3-X04"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원 위의 점마다 반지름을 하나씩 그을 수 있어요 — 원 위의 점은 셀 수 없이 많아요.","그래서 「셀 수 없이 많아요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"한 원에 원의 중심은 몇 개 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M3-2-u3-X03"},{"t":"4개","mis":"M3-2-u3-X03"},{"t":"셀 수 없이 많아요","mis":"M3-2-u3-X03"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원의 중심은 원의 가장 안쪽 한 점이에요 — 한 원에 하나뿐이에요.","그래서 「1개」가 알맞아요."],"asset":null},{"stem":"한 원에서 반지름의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"그은 자리마다 달라요","mis":"M3-2-u3-X05"},{"t":"위쪽으로 그은 것이 가장 길어요","mis":"M3-2-u3-X05"},{"t":"알 수 없어요","mis":"M3-2-u3-X05"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원의 중심에서 원 위의 어느 점까지나 길이가 같아요.","그래서 「모두 같아요」가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#7','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'sa','auto','띠종이에 누름 못에서 1, 2, 3, 4 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 2 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u3-C2","difficulty":2,"kind":"sa","stem":"띠종이에 누름 못에서 1, 2, 3, 4 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 2 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 2 cm예요."],"variant_rule":{"alt":[{"stem":"띠종이에 누름 못에서 2, 3, 4, 5 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 4 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 4 cm예요."],"asset":null},{"stem":"띠종이에 누름 못에서 1, 3, 5, 6 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 6 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#8','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','반지름은 어느 선분인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X02']::text[],true,'{"seq":8,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"반지름은 어느 선분인가요?","options":[{"t":"선분 ㅇㄱ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-2-u3-X07"},{"t":"선분 ㅇㄹ","mis":"M3-2-u3-X02"},{"t":"셋 다 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이어요.","선분 ㄴㄷ은 원 위의 두 점을 이었고, 점 ㄹ은 원 안의 점이에요.","반지름은 선분 ㅇㄱ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[88.7,35.9,"ne"],"ㄴ":[31.3,35.9,"nw"],"ㄷ":[53.5,96.9,"s"],"ㄹ":[74.4,72.1,"se"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㄴ","ㄷ"],["ㅇ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분은 어느 것인가요?","options":[{"t":"선분 ㅇㄷ","correct":true},{"t":"선분 ㄹㅁ","mis":"M3-2-u3-X07"},{"t":"선분 ㅇㅂ","mis":"M3-2-u3-X02"},{"t":"셋 다 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이어요.","선분 ㄹㅁ은 원 위의 두 점을 이었고, 점 ㅂ은 원 안의 점이에요.","반지름은 선분 ㅇㄷ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄷ":[47.2,24.8,"n"],"ㄹ":[27.5,78.8,"sw"],"ㅁ":[92.5,78.8,"se"],"ㅂ":[76.2,50.6,"ne"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄷ"],["ㄹ","ㅁ"],["ㅇ","ㅂ"]]}],"tag":false}},{"stem":"이 원의 반지름을 찾아보세요. 어느 선분인가요?","options":[{"t":"선분 ㅇㄴ","correct":true},{"t":"선분 ㄷㄹ","mis":"M3-2-u3-X07"},{"t":"선분 ㅇㅁ","mis":"M3-2-u3-X02"},{"t":"셋 다 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["반지름은 원의 중심 ㅇ과 원 위의 한 점을 이어요.","선분 ㄷㄹ은 원 위의 두 점을 이었고, 점 ㅁ은 원 안의 점이에요.","반지름은 선분 ㅇㄴ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄴ":[23.1,66.5,"w"],"ㄷ":[72.8,95.2,"s"],"ㄹ":[84.1,31.3,"ne"],"ㅁ":[53.6,42.4,"ne"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄴ"],["ㄷ","ㄹ"],["ㅇ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#9','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',2,'mc','auto','자로 한 점에서 같은 길이만큼 떨어진 곳에 점을 여러 개 찍어 원을 만들고 있어요. 원에 더 가까워지려면 어떻게 해야 하나요?',ARRAY['M3-2-u3-X02','M3-2-u3-X05','M3-2-u3-X01']::text[],true,'{"seq":9,"concept":"M3-2-u3-C2","difficulty":2,"kind":"mc","stem":"자로 한 점에서 같은 길이만큼 떨어진 곳에 점을 여러 개 찍어 원을 만들고 있어요. 원에 더 가까워지려면 어떻게 해야 하나요?","options":[{"t":"점을 빈틈없이 많이 찍어요","correct":true},{"t":"점을 몇 개만 찍어요","mis":"M3-2-u3-X02"},{"t":"점마다 길이를 다르게 해요","mis":"M3-2-u3-X05"},{"t":"점을 한 줄로 찍어요","mis":"M3-2-u3-X01"}],"explanation":["원은 한 점에서 같은 길이만큼 떨어진 점들이 모인 것이에요.","그 한 점이 원의 중심, 같은 길이가 반지름이에요.","그래서 「점을 빈틈없이 많이 찍어요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"한 점에서 3 cm 떨어진 곳에 점을 빈틈없이 많이 찍었어요. 어떤 모양이 될까요?","options":[{"t":"반지름이 3 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X07"},{"t":"한 변이 3 cm인 정사각형","mis":"M3-2-u3-X01"},{"t":"길이가 3 cm인 선분","mis":"M3-2-u3-X02"}],"explanation":["원은 한 점에서 같은 길이만큼 떨어진 점들이 모인 것이에요.","그 한 점이 원의 중심, 같은 길이가 반지름이에요.","그래서 「반지름이 3 cm인 원」이 알맞아요."],"asset":null},{"stem":"포이를 줄을 잡은 손을 중심으로 돌렸어요. 줄을 더 길게 잡으면 어떻게 되나요?","options":[{"t":"더 큰 원이 생겨요","correct":true},{"t":"더 작은 원이 생겨요","mis":"M3-2-u3-X05"},{"t":"원의 크기는 그대로예요","mis":"M3-2-u3-X05"},{"t":"원이 아닌 모양이 돼요","mis":"M3-2-u3-X01"}],"explanation":["원은 한 점에서 같은 길이만큼 떨어진 점들이 모인 것이에요.","그 한 점이 원의 중심, 같은 길이가 반지름이에요.","그래서 「더 큰 원이 생겨요」가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_basic#10','math',3,2,'u3','L02','g3_2_math_u3_L02_basic','lesson_basic','M3-2-u3-C2',3,'ox','auto','한 원에서 반지름은 그은 자리에 따라 길이가 달라요.',ARRAY['M3-2-u3-X05']::text[],true,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"한 원에서 반지름은 그은 자리에 따라 길이가 달라요.","answer":"X","reason_options":[{"t":"원의 중심에서 원 위의 어느 점까지나 길이가 같아서","correct":true},{"t":"그은 방향마다 길이가 달라서","mis":"M3-2-u3-X05"}],"mis":"M3-2-u3-X05","explanation":["원은 중심에서 같은 길이만큼 떨어진 점들로 이루어져요.","그래서 원 위의 어느 점까지 그어도 반지름의 길이는 같아요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"한 원에서 위쪽으로 그은 반지름이 옆으로 그은 반지름보다 길어요.","answer":"X","reason_options":[{"t":"원의 중심에서 원 위의 어느 점까지나 길이가 같아서","correct":true},{"t":"그은 방향마다 길이가 달라서","mis":"M3-2-u3-X05"}],"explanation":["원은 중심에서 같은 길이만큼 떨어진 점들로 이루어져요.","그래서 원 위의 어느 점까지 그어도 반지름의 길이는 같아요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"원의 중심에서 원 위의 점까지 그은 선분은 점마다 길이가 달라요.","answer":"X","reason_options":[{"t":"원의 중심에서 원 위의 어느 점까지나 길이가 같아서","correct":true},{"t":"그은 방향마다 길이가 달라서","mis":"M3-2-u3-X05"}],"explanation":["원은 중심에서 같은 길이만큼 떨어진 점들로 이루어져요.","그래서 원 위의 어느 점까지 그어도 반지름의 길이는 같아요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#1','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C1',2,'mc','auto','원이 아닌 것은 어느 것인가요?',ARRAY['M3-2-u3-X16']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원이 아닌 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M3-2-u3-X16"},{"t":"㉯","mis":"M3-2-u3-X16"},{"t":"㉱","mis":"M3-2-u3-X16"}],"explanation":["크기는 달라도 똑같이 둥글면 모두 원이에요.","㉰는 옆(위아래)으로 조금 길쭉해요 — 원이 아니에요.","「아닌 것」을 묻는 문제예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],36.0]]},{"w":90,"h":90,"circle":[[[45,45],24.0]]},{"w":90,"h":90,"oval":[[45,45,37.5,30.0]]},{"w":90,"h":90,"circle":[[[45,45],30.0]]}]},"variant_rule":{"alt":[{"stem":"한쪽으로 조금 길쭉해서 원이라고 할 수 없는 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u3-X16"},{"t":"㉰","mis":"M3-2-u3-X16"},{"t":"㉱","mis":"M3-2-u3-X16"}],"explanation":["크기는 달라도 똑같이 둥글면 모두 원이에요.","㉯는 옆(위아래)으로 조금 길쭉해요 — 원이 아니에요.","「아닌 것」을 묻는 문제예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],24.0]]},{"w":90,"h":90,"oval":[[45,45,37.5,31.5]]},{"w":90,"h":90,"circle":[[[45,45],30.0]]},{"w":90,"h":90,"circle":[[[45,45],36.0]]}]}},{"stem":"원이 아닌 모양을 찾아보세요. 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u3-X16"},{"t":"㉰","mis":"M3-2-u3-X16"},{"t":"㉱","mis":"M3-2-u3-X16"}],"explanation":["크기는 달라도 똑같이 둥글면 모두 원이에요.","㉮는 옆(위아래)으로 조금 길쭉해요 — 원이 아니에요.","「아닌 것」을 묻는 문제예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"oval":[[45,45,37.5,33.0]]},{"w":90,"h":90,"circle":[[[45,45],30.0]]},{"w":90,"h":90,"circle":[[[45,45],36.0]]},{"w":90,"h":90,"circle":[[[45,45],24.0]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.gradi