INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#2','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C1',2,'mc','auto','본떠서 원을 그릴 수 있는 물건은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":2,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"동전","correct":true},{"t":"공책","mis":"M3-2-u3-X01"},{"t":"삼각자","mis":"M3-2-u3-X01"},{"t":"지우개","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","동전을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"컵의 바닥","correct":true},{"t":"필통 옆면","mis":"M3-2-u3-X01"},{"t":"삼각자","mis":"M3-2-u3-X01"},{"t":"책","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","컵의 바닥을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"병뚜껑","correct":true},{"t":"색종이","mis":"M3-2-u3-X01"},{"t":"달걀","mis":"M3-2-u3-X01"},{"t":"공책","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","병뚜껑을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#3','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C1',3,'sa','auto','원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C1","difficulty":3,"kind":"sa","stem":"원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 2개, 원 밖의 점 1개는 세지 않아요.","원 위의 점은 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[95.2,47.2,"e"],"ㄴ":[47.2,24.8,"n"],"ㄷ":[47.2,95.2,"s"],"ㄹ":[69.4,76.2,"se"],"ㅁ":[47.7,55.5,"nw"],"ㅂ":[85.3,16.2,"ne"]},"circle":[[[60,60],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 1개, 원 밖의 점 2개는 세지 않아요.","원 위의 점은 2개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[72.8,24.8,"n"],"ㄴ":[24.8,72.8,"w"],"ㄷ":[77.9,70.3,"se"],"ㄹ":[27.5,21.2,"nw"],"ㅁ":[68.5,108.0,"s"]},"circle":[[[60,60],37.5]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원 위에 있는 점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["원은 굽은 선 — 선 위에 놓인 점만 원 위의 점이에요.","원 안의 점 1개, 원 밖의 점 1개는 세지 않아요.","원 위의 점은 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[97.5,60.0,"e"],"ㄴ":[60.0,22.5,"n"],"ㄷ":[22.5,60.0,"w"],"ㄹ":[60.0,97.5,"s"],"ㅁ":[73.3,46.7,"ne"],"ㅂ":[24.2,95.8,"sw"]},"circle":[[[60,60],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#4','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'sa','auto','점 ㅇ은 원의 중심이에요. 선분 ㅇㄱ이 3 cm일 때, 선분 ㅇㄴ과 선분 ㅇㄷ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C2","difficulty":3,"kind":"sa","stem":"점 ㅇ은 원의 중심이에요. 선분 ㅇㄱ이 3 cm일 때, 선분 ㅇㄴ과 선분 ㅇㄷ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 3 cm예요.","3 + 3 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[88.7,35.9,"ne"],"ㄴ":[24.8,47.2,"w"],"ㄷ":[66.5,96.9,"s"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[78.7,53.1],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅇ은 원의 중심이에요. 선분 ㅇㄱ이 4 cm일 때, 선분 ㅇㄴ과 선분 ㅇㄷ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 4 cm예요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[27.5,78.8,"sw"],"ㄴ":[92.5,78.8,"se"],"ㄷ":[60.0,22.5,"n"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[40.4,63.5],"4 cm"]]}],"tag":false}},{"stem":"점 ㅇ은 원의 중심이에요. 선분 ㅇㄱ이 5 cm일 때, 선분 ㅇㄴ과 선분 ㅇㄷ의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㅇㄱ·ㅇㄴ·ㅇㄷ은 모두 반지름이에요.","한 원에서 반지름은 모두 5 cm예요.","5 + 5 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[47.2,95.2,"s"],"ㄷ":[97.4,63.3,"e"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[63.4,40.4],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#5','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'error','auto','원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X04','M3-2-u3-X16']::text[],true,'{"seq":5,"concept":"M3-2-u3-C2","difficulty":3,"kind":"error","stem":"원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「한 원에 반지름은 1개뿐이야.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"시우 — 「원의 중심은 한 원에 하나야.」","mis":"M3-2-u3-X16"},{"t":"은우 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"하랑 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","서윤의 말 「한 원에 반지름은 1개뿐이야」가 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「원의 중심은 원 위에 있어.」","correct":true,"mis_target":"M3-2-u3-X03"},{"t":"은우 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"하랑 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「원은 꼭짓점이 없어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","시우의 말 「원의 중심은 원 위에 있어」가 잘못이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「반지름은 그은 자리마다 길이가 달라.」","correct":true,"mis_target":"M3-2-u3-X05"},{"t":"하랑 — 「원의 중심은 한 원에 하나야.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"},{"t":"민호 — 「원은 꼭짓점이 없어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","은우의 말 「반지름은 그은 자리마다 길이가 달라」가 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#6','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'mc','auto','띠종이의 구멍은 누름 못에서 1, 2, 3, 4 cm 떨어져 있어요. 가장 큰 원이 그려지는 구멍은 누름 못에서 몇 cm 떨어진 구멍인가요?',ARRAY['M3-2-u3-X16','M3-2-u3-X05']::text[],true,'{"seq":6,"concept":"M3-2-u3-C2","difficulty":3,"kind":"mc","stem":"띠종이의 구멍은 누름 못에서 1, 2, 3, 4 cm 떨어져 있어요. 가장 큰 원이 그려지는 구멍은 누름 못에서 몇 cm 떨어진 구멍인가요?","options":[{"t":"4 cm","correct":true},{"t":"1 cm","mis":"M3-2-u3-X16"},{"t":"2 cm","mis":"M3-2-u3-X05"},{"t":"3 cm","mis":"M3-2-u3-X05"}],"explanation":["누름 못에서 연필 구멍까지가 반지름이에요.","반지름이 길수록 원이 커요.","가장 먼 구멍 — 4 cm예요."],"variant_rule":{"alt":[{"stem":"띠종이의 구멍은 누름 못에서 3, 5, 6, 2 cm 떨어져 있어요. 가장 작은 원이 그려지는 구멍은 누름 못에서 몇 cm 떨어진 구멍인가요?","options":[{"t":"2 cm","correct":true},{"t":"3 cm","mis":"M3-2-u3-X05"},{"t":"5 cm","mis":"M3-2-u3-X05"},{"t":"6 cm","mis":"M3-2-u3-X16"}],"explanation":["누름 못에서 연필 구멍까지가 반지름이에요.","반지름이 짧을수록 원이 작아요.","가장 가까운 구멍 — 2 cm예요."],"asset":null},{"stem":"띠종이의 구멍은 누름 못에서 4, 6, 1, 3 cm 떨어져 있어요. 가장 큰 원이 그려지는 구멍은 누름 못에서 몇 cm 떨어진 구멍인가요?","options":[{"t":"6 cm","correct":true},{"t":"4 cm","mis":"M3-2-u3-X05"},{"t":"1 cm","mis":"M3-2-u3-X16"},{"t":"3 cm","mis":"M3-2-u3-X05"}],"explanation":["누름 못에서 연필 구멍까지가 반지름이에요.","반지름이 길수록 원이 커요.","가장 먼 구멍 — 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#7','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',3,'ox','auto','원의 중심은 원 위에 있어요.',ARRAY['M3-2-u3-X03']::text[],true,'{"seq":7,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"원의 중심은 원 위에 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"mis":"M3-2-u3-X03","explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"한 원에 원의 중심은 여러 개 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"누름 못이 꽂힌 점은 원 위의 점이에요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#8','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'sa','auto','원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 6 cm이고 삼각형의 세 변의 길이의 합은 16 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C2","difficulty":4,"kind":"sa","stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 6 cm이고 삼각형의 세 변의 길이의 합은 16 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 16 − 6 = 10(cm).","반지름 하나는 10의 반 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[95.2,47.2,"e"],"ㄴ":[31.3,35.9,"nw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 5 cm이고 삼각형의 세 변의 길이의 합은 13 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 13 − 5 = 8(cm).","반지름 하나는 8의 반 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"n"],"ㄱ":[24.8,72.8,"w"],"ㄴ":[88.7,84.1,"se"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 7 cm이고 삼각형의 세 변의 길이의 합은 19 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 19 − 7 = 12(cm).","반지름 하나는 12의 반 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[31.3,84.1,"sw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#9','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'mc','auto','반지름이 3 cm인 원이 있어요. 점 ㄴ은 원 안에, 점 ㄷ은 원 밖에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u3-X02','M3-2-u3-X16']::text[],true,'{"seq":9,"concept":"M3-2-u3-C2","difficulty":4,"kind":"mc","stem":"반지름이 3 cm인 원이 있어요. 점 ㄴ은 원 안에, 점 ㄷ은 원 밖에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분 ㅇㄴ은 3 cm보다 짧고, 선분 ㅇㄷ은 3 cm보다 길어요","correct":true},{"t":"선분 ㅇㄴ과 선분 ㅇㄷ은 모두 3 cm예요","mis":"M3-2-u3-X02"},{"t":"선분 ㅇㄴ은 3 cm보다 길고, 선분 ㅇㄷ은 3 cm보다 짧아요","mis":"M3-2-u3-X16"},{"t":"선분 ㅇㄷ이 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["원 위의 점까지는 꼭 반지름 3 cm예요.","원 안의 점은 그보다 가깝고, 원 밖의 점은 그보다 멀어요.","원 위에 있지 않은 점까지의 선분은 반지름이 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원이 있어요. 점 ㄴ은 원 안에, 점 ㄷ은 원 밖에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분 ㅇㄴ은 4 cm보다 짧고, 선분 ㅇㄷ은 4 cm보다 길어요","correct":true},{"t":"선분 ㅇㄴ과 선분 ㅇㄷ은 모두 4 cm예요","mis":"M3-2-u3-X02"},{"t":"선분 ㅇㄴ은 4 cm보다 길고, 선분 ㅇㄷ은 4 cm보다 짧아요","mis":"M3-2-u3-X16"},{"t":"선분 ㅇㄷ이 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["원 위의 점까지는 꼭 반지름 4 cm예요.","원 안의 점은 그보다 가깝고, 원 밖의 점은 그보다 멀어요.","원 위에 있지 않은 점까지의 선분은 반지름이 아니에요."],"asset":null},{"stem":"반지름이 5 cm인 원이 있어요. 점 ㄴ은 원 안에, 점 ㄷ은 원 밖에 있어요. 원의 중심 ㅇ에서 두 점까지의 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"선분 ㅇㄴ은 5 cm보다 짧고, 선분 ㅇㄷ은 5 cm보다 길어요","correct":true},{"t":"선분 ㅇㄴ과 선분 ㅇㄷ은 모두 5 cm예요","mis":"M3-2-u3-X02"},{"t":"선분 ㅇㄴ은 5 cm보다 길고, 선분 ㅇㄷ은 5 cm보다 짧아요","mis":"M3-2-u3-X16"},{"t":"선분 ㅇㄷ이 반지름이에요","mis":"M3-2-u3-X02"}],"explanation":["원 위의 점까지는 꼭 반지름 5 cm예요.","원 안의 점은 그보다 가깝고, 원 밖의 점은 그보다 멀어요.","원 위에 있지 않은 점까지의 선분은 반지름이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L02_challenge#10','math',3,2,'u3','L02','g3_2_math_u3_L02_challenge','lesson_challenge','M3-2-u3-C2',4,'essay','teacher','운동장에 말뚝 하나와 줄을 써서 큰 원을 그리려고 해요. 그리는 방법을 쓰고, 그렇게 하면 원이 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":4,"kind":"essay","stem":"운동장에 말뚝 하나와 줄을 써서 큰 원을 그리려고 해요. 그리는 방법을 쓰고, 그렇게 하면 원이 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 말뚝을 한 곳에 박아 원의 중심으로 정하고, 줄의 한쪽 끝을 말뚝에 묶는다. 줄의 다른 끝에 막대를 매어 줄을 팽팽하게 당긴 채 한 바퀴 돌며 땅에 선을 긋는다. 말뚝에서 같은 길이만큼 떨어진 점들이 이어지므로 원이 된다.","scoring_points":["말뚝을 원의 중심으로 정했는가","줄을 팽팽하게 하여 같은 길이로 돌린다고 썼는가","중심에서 같은 거리의 점들이라 원이 된다는 까닭을 썼는가"]},"explanation":["한 점을 중심으로 정해요.","줄의 길이(반지름)를 그대로 두고 한 바퀴 돌려요.","중심에서 같은 길이만큼 떨어진 점들이 모이면 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#1','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','원의 중심을 지나는 선분은 어느 것인가요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":1,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"원의 중심을 지나는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄷㄹ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅂ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄱㄴ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[93.8,40.5,"ne"],"ㄴ":[26.2,79.5,"sw"],"ㄷ":[66.8,21.6,"n"],"ㄹ":[23.4,46.7,"w"],"ㅁ":[46.7,96.6,"s"],"ㅂ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"지름은 어느 선분인가요?","options":[{"t":"선분 ㄷㅅ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X06"},{"t":"선분 ㄹㅁ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄷㅅ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄷ":[60.0,21.0,"n"],"ㅅ":[60.0,99.0,"s"],"ㄱ":[30.1,34.9,"nw"],"ㄴ":[30.1,85.1,"sw"],"ㄹ":[85.1,89.9,"se"],"ㅁ":[85.1,30.1,"ne"]},"circle":[[[60,60],39.0]],"seg":[["ㄷ","ㅅ"],["ㄱ","ㄴ"],["ㄹ","ㅁ"]]}],"tag":false}},{"stem":"이 원의 지름을 찾아보세요. 어느 선분인가요?","options":[{"t":"선분 ㅁㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-2-u3-X06"},{"t":"선분 ㅂㄱ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㅁㄹ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㅁ":[30.1,34.9,"nw"],"ㄹ":[89.9,85.1,"se"],"ㄴ":[21.6,66.8,"w"],"ㄷ":[60.0,99.0,"s"],"ㅂ":[99.0,60.0,"e"],"ㄱ":[53.2,21.6,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㅁ","ㄹ"],["ㄴ","ㄷ"],["ㅂ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#2','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','원 위의 두 점을 이은 선분이 원의 중심을 지날 때, 그 선분을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"원 위의 두 점을 이은 선분이 원의 중심을 지날 때, 그 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「지름」이에요."],"variant_rule":{"alt":[{"stem":"지름은 원 위의 두 점을 이은 선분 가운데 어떤 선분인가요?","options":[{"t":"원의 중심을 지나는 선분","correct":true},{"t":"가장 짧은 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이은 선분","mis":"M3-2-u3-X07"},{"t":"원 밖의 점을 지나는 선분","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「원의 중심을 지나는 선분」이에요."],"asset":null},{"stem":"시계에서 12와 6을 잇는 선분은 시곗바늘이 도는 가운데를 지나요. 이 선분은 시계 모양 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「지름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#3','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'sa','auto','지름이 6 cm인 원에 지름을 하나 더 그었어요. 새로 그은 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"지름이 6 cm인 원에 지름을 하나 더 그었어요. 새로 그은 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","6 cm예요."],"variant_rule":{"alt":[{"stem":"선풍기 모양 원의 지름이 8 cm예요. 다른 쪽으로 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","8 cm예요."],"asset":null},{"stem":"한 원에 그은 지름 하나가 10 cm예요. 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","10 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#4','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',1,'mc','auto','한 원에 지름은 몇 개 그을 수 있나요?',ARRAY['M3-2-u3-X04']::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"한 원에 지름은 몇 개 그을 수 있나요?","options":[{"t":"셀 수 없이 많아요","correct":true},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"},{"t":"4개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「셀 수 없이 많아요」예요."],"variant_rule":{"alt":[{"stem":"한 원에서 지름의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"그은 방향마다 달라요","mis":"M3-2-u3-X05"},{"t":"가로로 그은 것이 가장 길어요","mis":"M3-2-u3-X05"},{"t":"알 수 없어요","mis":"M3-2-u3-X05"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「모두 같아요」예요."],"asset":null},{"stem":"한 원에서 지름은 모두 어느 점을 지나나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X06"},{"t":"원 밖의 한 점","mis":"M3-2-u3-X02"},{"t":"지나는 점이 모두 달라요","mis":"M3-2-u3-X06"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「원의 중심」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
