INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#6','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',2,'mc','auto','지름을 바르게 긋는 방법은 어느 것인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07','M3-2-u3-X02']::text[],true,'{"seq":6,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"지름을 바르게 긋는 방법은 어느 것인가요?","options":[{"t":"원의 중심에 자를 먼저 대고, 자와 원이 만나는 두 점을 이어요","correct":true},{"t":"원 위의 아무 두 점이나 이어요","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이어요","mis":"M3-2-u3-X07"},{"t":"원 밖의 두 점을 이어요","mis":"M3-2-u3-X02"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"variant_rule":{"alt":[{"stem":"원 모양 종이에 지름을 그으려고 해요. 자를 어디에 먼저 대야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 아무 점","mis":"M3-2-u3-X06"},{"t":"원 밖의 한 점","mis":"M3-2-u3-X02"},{"t":"원의 맨 위쪽 점","mis":"M3-2-u3-X06"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"asset":null},{"stem":"지름을 그을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"원의 중심에 자를 먼저 대고, 자와 원이 만나는 두 점을 이어요","correct":true},{"t":"원 위의 아무 두 점이나 이어요","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이어요","mis":"M3-2-u3-X07"},{"t":"원 밖의 두 점을 이어요","mis":"M3-2-u3-X02"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
