INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#8','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',2,'sa','auto','그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C3","difficulty":2,"kind":"sa","stem":"그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 2개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"nw"],"ㄱ":[96.6,46.7,"e"],"ㄴ":[23.4,73.3,"w"],"ㄷ":[53.2,21.6,"n"],"ㄹ":[66.8,98.4,"s"],"ㅁ":[26.2,40.5,"nw"],"ㅂ":[46.7,96.6,"s"],"ㅅ":[93.8,79.5,"se"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[99.0,60.0,"e"],"ㄴ":[21.0,60.0,"w"],"ㄷ":[79.5,26.2,"ne"],"ㄹ":[40.5,93.8,"sw"],"ㅁ":[40.5,26.2,"nw"],"ㅂ":[79.5,93.8,"se"],"ㅅ":[23.4,73.3,"w"],"ㅈ":[66.8,98.4,"s"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 1개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"nw"],"ㄱ":[87.6,32.4,"ne"],"ㄴ":[32.4,87.6,"sw"],"ㄷ":[53.2,21.6,"n"],"ㄹ":[21.6,53.2,"w"],"ㅁ":[53.2,98.4,"s"],"ㅂ":[93.8,79.5,"se"],"ㅅ":[98.4,53.2,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qki