INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_basic#10','math',3,2,'u3','L03','g3_2_math_u3_L03_basic','lesson_basic','M3-2-u3-C3',3,'ox','auto','원 위의 두 점을 이은 선분은 모두 지름이에요.',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":10,"concept":"M3-2-u3-C3","difficulty":3,"kind":"ox","stem":"원 위의 두 점을 이은 선분은 모두 지름이에요.","answer":"X","reason_options":[{"t":"원의 중심을 지나는 선분만 지름이라서","correct":true},{"t":"원 위의 두 점을 이으면 모두 지름이라서","mis":"M3-2-u3-X06"}],"mis":"M3-2-u3-X06","explanation":["원 위의 두 점을 이어도 중심을 지나지 않는 선분이 많아요.","원의 중심을 지나는 선분만 지름이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"원 안에 그은 곧은 선분은 모두 지름이에요.","answer":"X","reason_options":[{"t":"원의 중심을 지나는 선분만 지름이라서","correct":true},{"t":"원 위의 두 점을 이으면 모두 지름이라서","mis":"M3-2-u3-X06"}],"explanation":["원 위의 두 점을 이어도 중심을 지나지 않는 선분이 많아요.","원의 중심을 지나는 선분만 지름이에요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"원 위의 두 점을 이으면 언제나 원의 중심을 지나요.","answer":"X","reason_options":[{"t":"원의 중심을 지나는 선분만 지름이라서","correct":true},{"t":"원 위의 두 점을 이으면 모두 지름이라서","mis":"M3-2-u3-X06"}],"explanation":["원 위의 두 점을 이어도 중심을 지나지 않는 선분이 많아요.","원의 중심을 지나는 선분만 지름이에요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#1','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',2,'error','auto','지름에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X16']::text[],true,'{"seq":1,"concept":"M3-2-u3-C3","difficulty":2,"kind":"error","stem":"지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「지름은 원 위의 아무 두 점이나 이으면 돼.」","correct":true,"mis_target":"M3-2-u3-X06"},{"t":"지아 — 「한 원에서 지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"민호 — 「지름은 셀 수 없이 많이 그을 수 있어.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「지름은 원 위의 두 점을 이어.」","mis":"M3-2-u3-X16"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","한 원에서 지름은 셀 수 없이 많고 길이가 모두 같아요.","하랑의 말이 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「한 원에 지름은 하나뿐이야.」","correct":true,"mis_target":"M3-2-u3-X04"},{"t":"민호 — 「지름은 원의 중심을 지나.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「한 원에서 지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"하늘 — 「지름은 원 위의 두 점을 이어.」","mis":"M3-2-u3-X16"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","한 원에서 지름은 셀 수 없이 많고 길이가 모두 같아요.","지아의 말이 잘못이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「지름은 원의 중심과 원 위의 한 점을 이은 선분이야.」","correct":true,"mis_target":"M3-2-u3-X07"},{"t":"가람 — 「지름은 원의 중심을 지나.」","mis":"M3-2-u3-X16"},{"t":"하늘 — 「한 원에서 지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"도윤 — 「지름은 셀 수 없이 많이 그을 수 있어.」","mis":"M3-2-u3-X16"}],"explanation":["지름은 원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 선분이에요.","한 원에서 지름은 셀 수 없이 많고 길이가 모두 같아요.","민호의 말이 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#2','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',2,'mc','auto','선분 세 개 가운데 지름은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":2,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"선분 세 개 가운데 지름은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.","options":[{"t":"선분 ㅁㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-2-u3-X06"},{"t":"선분 ㅂㄱ","mis":"M3-2-u3-X06"},{"t":"지름이 없어요","mis":"M3-2-u3-X06"}],"explanation":["선분 ㄴㄷ은 원의 중심 가까이를 지나지만 중심을 지나지는 않아요.","원의 중심 ㅇ을 꼭 지나는 것은 선분 ㅁㄹ이에요.","자를 원의 중심에 대어 확인해요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㅁ":[91.9,37.6,"ne"],"ㄹ":[28.1,82.4,"sw"],"ㄴ":[43.5,24.7,"nw"],"ㄷ":[68.8,98.0,"s"],"ㅂ":[24.7,43.5,"nw"],"ㄱ":[97.7,70.1,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㅁ","ㄹ"],["ㄴ","ㄷ"],["ㅂ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 선분 세 개 가운데 지름은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.","options":[{"t":"선분 ㄴㅂ","correct":true},{"t":"선분 ㄹㅁ","mis":"M3-2-u3-X06"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X06"},{"t":"지름이 없어요","mis":"M3-2-u3-X06"}],"explanation":["선분 ㄹㅁ은 원의 중심 가까이를 지나지만 중심을 지나지는 않아요.","원의 중심 ㅇ을 꼭 지나는 것은 선분 ㄴㅂ이에요.","자를 원의 중심에 대어 확인해요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄴ":[56.6,21.1,"n"],"ㅂ":[63.4,98.9,"s"],"ㄹ":[21.1,56.6,"w"],"ㅁ":[97.3,71.4,"e"],"ㄱ":[28.1,82.4,"sw"],"ㄷ":[87.6,32.4,"ne"]},"circle":[[[60,60],39.0]],"seg":[["ㄴ","ㅂ"],["ㄹ","ㅁ"],["ㄱ","ㄷ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 선분 세 개 가운데 지름은 어느 것인가요? 원의 중심 ㅇ을 잘 보세요.","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄷㄹ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅂ","mis":"M3-2-u3-X06"},{"t":"지름이 없어요","mis":"M3-2-u3-X06"}],"explanation":["선분 ㄷㄹ은 원의 중심 가까이를 지나지만 중심을 지나지는 않아요.","원의 중심 ㅇ을 꼭 지나는 것은 선분 ㄱㄴ이에요.","자를 원의 중심에 대어 확인해요."],"asset":{"type":"geo","items":[{"w":12