INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#3','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"원의 가장 안쪽에 있는 한 점"},{"l":"반지름","r":"원의 중심과 원 위의 한 점을 이은 선분"},{"l":"지름","r":"원의 중심을 지나고 원 위의 두 점을 이은 선분"}],"mis":"M3-2-u3-X07","explanation":["원의 중심: 원의 가장 안쪽 한 점.","반지름: 중심에서 원 위의 한 점까지.","지름: 중심을 지나 원 위의 두 점을 이은 선분."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"한 원에 하나뿐이에요"},{"l":"반지름","r":"지름의 반이에요"},{"l":"지름","r":"원 안에 그을 수 있는 가장 긴 선분이에요"}],"explanation":["원의 중심: 원의 가장 안쪽 한 점.","반지름: 중심에서 원 위의 한 점까지.","지름: 중심을 지나 원 위의 두 점을 이은 선분."],"asset":null},{"stem":"이번에는 다른 그림이에요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심","r":"컴퍼스의 침을 꽂는 곳"},{"l":"반지름","r":"컴퍼스를 벌린 길이"},{"l":"지름","r":"원을 똑같이 둘로 나누는 선분"}],"explanation":["원의 중심: 원의 가장 안쪽 한 점.","반지름: 중심에서 원 위의 한 점까지.","지름: 중심을 지나 원 위의 두 점을 이은 선분."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#4','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',3,'sa','auto','선분 ㄱㄴ과 선분 ㄷㄹ은 모두 원의 중심 ㅇ을 지나요. 선분 ㄱㄴ이 6 cm일 때 선분 ㄷㄹ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"선분 ㄱㄴ과 선분 ㄷㄹ은 모두 원의 중심 ㅇ을 지나요. 선분 ㄱㄴ이 6 cm일 때 선분 ㄷㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 선분 모두 원의 중심을 지나 원 위의 두 점을 이었어요 — 지름이에요.","한 원에서 지름은 모두 같아요.","선분 ㄷㄹ도 6 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[99.0,60.0,"e"],"ㄴ":[21.0,60.0,"w"],"ㄷ":[73.3,23.4,"n"],"ㄹ":[46.7,96.6,"s"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"]],"lab":[[[88.1,52.5],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선분 ㄱㄴ과 선분 ㄷㄹ은 모두 원의 중심 ㅇ을 지나요. 선분 ㄱㄴ이 8 cm일 때 선분 ㄷㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 선분 모두 원의 중심을 지나 원 위의 두 점을 이었어요 — 지름이에요.","한 원에서 지름은 모두 같아요.","선분 ㄷㄹ도 8 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[89.9,34.9,"ne"],"ㄴ":[30.1,85.1,"sw"],"ㄷ":[46.7,23.4,"n"],"ㄹ":[73.3,96.6,"s"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"]],"lab":[[[76.7,36.2],"8 cm"]]}],"tag":false}},{"stem":"선분 ㄱㄴ과 선분 ㄷㄹ은 모두 원의 중심 ㅇ을 지나요. 선분 ㄱㄴ이 10 cm일 때 선분 ㄷㄹ은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["두 선분 모두 원의 중심을 지나 원 위의 두 점을 이었어요 — 지름이에요.","한 원에서 지름은 모두 같아요.","선분 ㄷㄹ도 10 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"ne"],"ㄱ":[53.2,21.6,"n"],"ㄴ":[66.8,98.4,"s"],"ㄷ":[21.6,53.2,"w"],"ㄹ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"]],"lab":[[[47.7,33.6],"10 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=