INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#8','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'sa','auto','이 원의 지름은 6 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"이 원의 지름은 6 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 3개예요.","지름은 모두 6 cm예요.","6 + 6 + 6 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[99.0,60.0,"e"],"ㄴ":[21.0,60.0,"w"],"ㄷ":[79.5,26.2,"ne"],"ㄹ":[40.5,93.8,"sw"],"ㅁ":[40.5,26.2,"nw"],"ㅂ":[79.5,93.8,"se"],"ㅅ":[23.4,73.3,"w"],"ㅈ":[66.8,98.4,"s"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 원의 지름은 8 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 1개예요.","지름은 모두 8 cm예요.","8 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"nw"],"ㄱ":[87.6,32.4,"ne"],"ㄴ":[32.4,87.6,"sw"],"ㄷ":[53.2,21.6,"n"],"ㄹ":[21.6,53.2,"w"],"ㅁ":[53.2,98.4,"s"],"ㅂ":[93.8,79.5,"se"],"ㅅ":[98.4,53.2,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}},{"stem":"이 원의 지름은 10 cm예요. 그림에서 지름인 선분의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["원의 중심 ㅇ을 지나는 선분(지름)을 먼저 찾아요 — 2개예요.","지름은 모두 10 cm예요.","10 + 10 = 20(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[93.8,40.5,"ne"],"ㄴ":[26.2,79.5,"sw"],"ㄷ":[60.0,21.0,"n"],"ㄹ":[60.0,99.0,"s"],"ㅁ":[34.9,30.1,"nw"],"ㅂ":[21.0,60.0,"w"],"ㅅ":[79.5,93.8,"se"],"ㅈ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode