INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#9','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'mc','auto','원 위에 점 8개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?',ARRAY['M3-2-u3-X15','M3-2-u3-X06','M3-2-u3-X04']::text[],true,'{"seq":9,"concept":"M3-2-u3-C3","difficulty":4,"kind":"mc","stem":"원 위에 점 8개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"8개","mis":"M3-2-u3-X15"},{"t":"28개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","8개를 둘씩 짝 지으면 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[60.0,21.0,"n"],"ㄴ":[87.6,32.4,"ne"],"ㄷ":[99.0,60.0,"e"],"ㄹ":[87.6,87.6,"se"],"ㅁ":[60.0,99.0,"s"],"ㅂ":[32.4,87.6,"sw"],"ㅅ":[21.0,60.0,"w"],"ㅈ":[32.4,32.4,"nw"]},"circle":[[[60,60],39.0]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원 위에 점 6개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M3-2-u3-X15"},{"t":"15개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","6개를 둘씩 짝 지으면 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[60.0,21.0,"n"],"ㄴ":[93.8,40.5,"ne"],"ㄷ":[93.8,79.5,"se"],"ㄹ":[60.0,99.0,"s"],"ㅁ":[26.2,79.5,"sw"],"ㅂ":[26.2,40.5,"nw"]},"circle":[[[60,60],39.0]]}],"tag":false}},{"stem":"원 위에 점 10개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"10개","mis":"M3-2-u3-X15"},{"t":"45개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","10개를 둘씩 짝 지으면 5개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts