INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L03_challenge#10','math',3,2,'u3','L03','g3_2_math_u3_L03_challenge','lesson_challenge','M3-2-u3-C3',4,'essay','teacher','원 위의 두 점을 이은 선분이 지름인지 아닌지 알아보는 방법을 쓰고, 지름이면 그 길이가 다른 지름과 어떤지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C3","difficulty":4,"kind":"essay","stem":"원 위의 두 점을 이은 선분이 지름인지 아닌지 알아보는 방법을 쓰고, 지름이면 그 길이가 다른 지름과 어떤지도 써 보세요.","answer_guide":{"answer":"예: 선분이 원의 중심을 지나는지 본다. 원의 중심에 자를 대어 선분이 중심을 지나면 지름이고, 지나지 않으면 지름이 아니다. 한 원에서 지름은 모두 길이가 같으므로 다른 지름과 길이가 같다.","scoring_points":["원의 중심을 지나는지 확인한다고 썼는가","지나면 지름, 아니면 지름이 아니라고 구별했는가","한 원에서 지름은 모두 같다고 썼는가"]},"explanation":["지름의 조건: 원 위의 두 점 + 원의 중심을 지남.","중심에 자를 대어 확인해요.","한 원의 지름은 모두 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#1','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',1,'sa','auto','반지름이 4 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"반지름이 4 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 지름은 반지름의 2배예요.","4 cm의 2배를 구해요.","4 × 2 = 8 — 지름은 8 cm예요."],"variant_rule":{"alt":[{"stem":"드림캐처 모양 원의 반지름이 5 cm예요. 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["한 원에서 지름은 반지름의 2배예요.","5 cm의 2배를 구해요.","5 × 2 = 10 — 지름은 10 cm예요."],"asset":null},{"stem":"반지름이 7 cm인 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["한 원에서 지름은 반지름의 2배예요.","7 cm의 2배를 구해요.","7 × 2 = 14 — 지름은 14 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#2','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',1,'sa','auto','지름이 10 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"지름이 10 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 원에서 반지름은 지름의 반이에요.","10 cm를 똑같이 둘로 나눠요.","10의 반은 5 — 반지름은 5 cm예요."],"variant_rule":{"alt":[{"stem":"접시 모양 원의 지름이 12 cm예요. 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에서 반지름은 지름의 반이에요.","12 cm를 똑같이 둘로 나눠요.","12의 반은 6 — 반지름은 6 cm예요."],"asset":null},{"stem":"지름이 8 cm인 원에 반지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 원에서 반지름은 지름의 반이에요.","8 cm를 똑같이 둘로 나눠요.","8의 반은 4 — 반지름은 4 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#3','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',1,'mc','auto','원 모양 종이를 똑같이 둘로 접었다 폈을 때 접힌 선은 원의 무엇인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"원 모양 종이를 똑같이 둘로 접었다 폈을 때 접힌 선은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"variant_rule":{"alt":[{"stem":"원을 똑같이 둘로 나누는 선분은 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 두 점을 이은 아무 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심","mis":"M3-2-u3-X03"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"asset":null},{"stem":"원 모양 종이를 똑같이 둘로 두 번 접었다 폈어요. 두 접힌 선이 만나는 점은 무엇인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"반지름","mis":"M3-2-u3-X07"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","지름 두 개가 만나는 점은 원의 중심이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#4','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',1,'mc','auto','점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?',ARRAY['M3-2-u3-X17']::text[],true,'{"seq":4,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄴ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[23.4,73.3,"w"],"ㄴ":[96.6,46.7,"e"],"ㄷ":[89.9,85.1,"se"],"ㄹ":[66.8,21.6,"n"],"ㅁ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄷ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[46.7,96.6,"s"],"ㄷ":[73.3,23.4,"n"],"ㄹ":[53.2,21.6,"n"],"ㅁ":[95.3,43.5,"ne"],"ㄴ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄹ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[40.5,26.2,"nw"],"ㄹ":[79.5,93.8,"se"],"ㅁ":[40.5,93.8,"sw"],"ㄴ":[99.0,60.0,"e"],"ㄷ":[60.0,99.0,"s"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㄴ"],["ㄱ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#5','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'mc','auto','한 원에서 지름과 반지름 사이의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u3-X08','M3-2-u3-X09']::text[],true,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"한 원에서 지름과 반지름 사이의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지름은 반지름의 2배예요","correct":true},{"t":"반지름은 지름의 2배예요","mis":"M3-2-u3-X08"},{"t":"지름과 반지름은 길이가 같아요","mis":"M3-2-u3-X09"},{"t":"지름은 반지름보다 2 cm 길어요","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「지름은 반지름의 2배예요」예요."],"variant_rule":{"alt":[{"stem":"한 원에서 반지름은 지름의 얼마인가요?","options":[{"t":"반","correct":true},{"t":"2배","mis":"M3-2-u3-X08"},{"t":"같아요","mis":"M3-2-u3-X09"},{"t":"3배","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「반」이에요."],"asset":null},{"stem":"반지름이 1 cm, 2 cm인 두 원의 지름은 2 cm, 4 cm예요. 어떤 관계가 있나요?","options":[{"t":"지름은 반지름의 2배예요","correct":true},{"t":"지름은 반지름의 반이에요","mis":"M3-2-u3-X08"},{"t":"지름은 반지름보다 1 cm 길어요","mis":"M3-2-u3-X09"},{"t":"지름과 반지름은 같아요","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「지름은 반지름의 2배예요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#6','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'sa','auto','점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ은 반지름 — 3 cm예요.","지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[96.6,46.7,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[76.0,47.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㅇㄱ은 반지름 — 4 cm예요.","지름은 반지름의 2배예요.","4 × 2 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[46.7,23.4,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[47.0,44.0],"4 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㅇㄱ은 반지름 — 5 cm예요.","지름은 반지름의 2배예요.","5 × 2 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[23.4,73.3,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[44.0,73.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
