INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#8','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C4',2,'mc','auto','카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":8,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 3 cm · 지름 6 cm","correct":true},{"t":"반지름 4 cm · 지름 4 cm","mis":"M3-2-u3-X09"},{"t":"반지름 6 cm · 지름 3 cm","mis":"M3-2-u3-X08"},{"t":"반지름 2 cm · 지름 8 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 3 cm인 원의 지름은 6 cm예요.","반지름 3 cm · 지름 6 cm가 같은 원이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 4 cm · 지름 8 cm","correct":true},{"t":"반지름 5 cm · 지름 5 cm","mis":"M3-2-u3-X09"},{"t":"반지름 8 cm · 지름 4 cm","mis":"M3-2-u3-X08"},{"t":"반지름 3 cm · 지름 12 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 4 cm인 원의 지름은 8 cm예요.","반지름 4 cm · 지름 8 cm가 같은 원이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 5 cm · 지름 10 cm","correct":true},{"t":"반지름 6 cm · 지름 6 cm","mis":"M3-2-u3-X09"},{"t":"반지름 10 cm · 지름 5 cm","mis":"M3-2-u3-X08"},{"t":"반지름 4 cm · 지름 16 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 5 cm인 원의 지름은 10 cm예요.","반지름 5 cm · 지름 10 cm가 같은 원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
