INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_basic#10','math',3,2,'u3','L04','g3_2_math_u3_L04_basic','lesson_basic','M3-2-u3-C5',3,'ox','auto','반지름이 4 cm인 원과 지름이 4 cm인 원은 크기가 같아요.',ARRAY['M3-2-u3-X10']::text[],true,'{"seq":10,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"반지름이 4 cm인 원과 지름이 4 cm인 원은 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 4 cm인 원은 지름이 8 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["반지름 4 cm인 원의 지름은 8 cm예요.","지름 4 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원은 반지름이 6 cm인 원과 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 6 cm인 원은 지름이 12 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 6 cm인 원의 지름은 12 cm예요.","지름 6 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null},{"stem":"반지름 8 cm인 원과 지름 8 cm인 원 가운데 어느 원도 더 크지 않아요.","answer":"X","reason_options":[{"t":"반지름 8 cm인 원은 지름이 16 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 8 cm인 원의 지름은 16 cm예요.","지름 8 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#1','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C4',2,'match','auto','반지름과 그 원의 지름을 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u3-C4","difficulty":2,"kind":"match","stem":"반지름과 그 원의 지름을 이으세요.","pairs":[{"l":"반지름 2 cm","r":"지름 4 cm"},{"l":"반지름 5 cm","r":"지름 10 cm"},{"l":"반지름 7 cm","r":"지름 14 cm"}],"mis":"M3-2-u3-X08","explanation":["지름은 반지름의 2배예요.","2 × 2 = 4, 5 × 2 = 10, 7 × 2 = 14.","반지름이 클수록 지름도 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 반지름과 그 원의 지름을 이으세요.","pairs":[{"l":"반지름 3 cm","r":"지름 6 cm"},{"l":"반지름 6 cm","r":"지름 12 cm"},{"l":"반지름 8 cm","r":"지름 16 cm"}],"explanation":["지름은 반지름의 2배예요.","3 × 2 = 6, 6 × 2 = 12, 8 × 2 = 16.","반지름이 클수록 지름도 커요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 반지름과 그 원의 지름을 이으세요.","pairs":[{"l":"반지름 4 cm","r":"지름 8 cm"},{"l":"반지름 9 cm","r":"지름 18 cm"},{"l":"반지름 1 cm","r":"지름 2 cm"}],"explanation":["지름은 반지름의 2배예요.","4 × 2 = 8, 9 × 2 = 18, 1 × 2 = 2.","반지름이 클수록 지름도 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#2','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',2,'mc','auto','가장 작은 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],true,'{"seq":2,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 8 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm.","가장 작은 원은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"가장 작은 원은 어느 것인가요? (㉠ 지름 6 cm, ㉡ 반지름 4 cm, ㉢ 반지름 2 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X16"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 8 cm, ㉢ 지름 4 cm.","가장 작은 원은 ㉢이에요."],"asset":null},{"stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 3 cm, ㉡ 지름 5 cm, ㉢ 지름 8 cm)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 5 cm, ㉢ 지름 8 cm.","가장 작은 원은 ㉡이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#3','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',3,'mc','auto','큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 지름 6 · ㉡ 반지름 4 · ㉢ 반지름 6 · ㉣ 지름 4, 단위 cm)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],true,'{"seq":3,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 지름 6 · ㉡ 반지름 4 · ㉢ 반지름 6 · ㉣ 지름 4, 단위 cm)","options":[{"t":"㉢, ㉡, ㉠, ㉣","correct":true},{"t":"㉠, ㉢, ㉡, ㉣","mis":"M3-2-u3-X10"},{"t":"㉢, ㉠, ㉡, ㉣","mis":"M3-2-u3-X10"},{"t":"㉣, ㉠, ㉡, ㉢","mis":"M3-2-u3-X16"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 6, ㉡ 8, ㉢ 12, ㉣ 4(cm).","큰 것부터 ㉢, ㉡, ㉠, ㉣이에요."],"variant_rule":{"alt":[{"stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 반지름 5 · ㉡ 지름 8 · ㉢ 반지름 3 · ㉣ 지름 12, 단위 cm)","options":[{"t":"㉣, ㉠, ㉡, ㉢","correct":true},{"t":"㉣, ㉡, ㉠, ㉢","mis":"M3-2-u3-X10"},{"t":"㉢, ㉡, ㉠, ㉣","mis":"M3-2-u3-X16"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M3-2-u3-X10"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 10, ㉡ 8, ㉢ 6, ㉣ 12(cm).","큰 것부터 ㉣, ㉠, ㉡, ㉢이에요."],"asset":null},{"stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 지름 9 · ㉡ 반지름 4 · ㉢ 반지름 7 · ㉣ 지름 5, 단위 cm)","options":[{"t":"㉢, ㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢, ㉣, ㉡","mis":"M3-2-u3-X10"},{"t":"㉢, ㉡, ㉠, ㉣","mis":"M3-2-u3-X10"},{"t":"㉣, ㉡, ㉠, ㉢","mis":"M3-2-u3-X16"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 9, ㉡ 8, ㉢ 14, ㉣ 5(cm).","큰 것부터 ㉢, ㉠, ㉡, ㉣이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#4','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',3,'sa','auto','반지름이 2 cm인 원과 5 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름을 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C8","difficulty":3,"kind":"sa","stem":"반지름이 2 cm인 원과 5 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름을 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["지름은 반지름의 2배 — 4 cm, 10 cm예요.","두 지름을 더해요.","4 + 10 = 14(cm)예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원과 4 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름을 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["지름은 반지름의 2배 — 6 cm, 8 cm예요.","두 지름을 더해요.","6 + 8 = 14(cm)예요."],"asset":null},{"stem":"반지름이 1 cm인 원과 6 cm인 원을 맞닿게 나란히 그렸어요. 두 원의 지름을 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["지름은 반지름의 2배 — 2 cm, 12 cm예요.","두 지름을 더해요.","2 + 12 = 14(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#5','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',3,'sa','auto','반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C8","difficulty":3,"kind":"sa","stem":"반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직사각형의 가로에는 원의 지름이 3개, 세로에는 1개 들어 있어요.","지름은 2 × 2 = 4(cm).","4 × 3 = 12(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"seg":[[[9.0,9.0],[99.0,9.0]],[[99.0,9.0],[99.0,39.0]],[[99.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["직사각형의 가로에는 원의 지름이 4개, 세로에는 1개 들어 있어요.","지름은 3 × 2 = 6(cm).","세로는 지름 하나 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"seg":[[[9.0,9.0],[129.0,9.0]],[[129.0,9.0],[129.0,39.0]],[[129.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false}},{"stem":"반지름이 4 cm인 원 3개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직사각형의 가로에는 원의 지름이 3개, 세로에는 1개 들어 있어요.","지름은 4 × 2 = 8(cm).","8 × 3 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"seg":[[[9.0,9.0],[99.0,9.0]],[[99.0,9.0],[99.0,39.0]],[[99.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#6','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',3,'mc','auto','반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?',ARRAY['M3-2-u3-X15','M3-2-u3-X08']::text[],true,'{"seq":6,"concept":"M3-2-u3-C8","difficulty":3,"kind":"mc","stem":"반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"8 cm","correct":true},{"t":"12 cm","mis":"M3-2-u3-X15"},{"t":"4 cm","mis":"M3-2-u3-X08"},{"t":"6 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 4개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 4개 = 지름 2개예요.","4 × 2 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[84.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"18 cm","correct":true},{"t":"24 cm","mis":"M3-2-u3-X15"},{"t":"9 cm","mis":"M3-2-u3-X08"},{"t":"12 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 6개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 6개 = 지름 3개예요.","6 × 3 = 18(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[114.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"반지름이 2 cm인 원 5개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"16 cm","correct":true},{"t":"20 cm","mis":"M3-2-u3-X15"},{"t":"8 cm","mis":"M3-2-u3-X08"},{"t":"10 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 8개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 8개 = 지름 4개예요.","4 × 4 = 16(cm)예요."],"asset":{"type":"geo","items":[{"w":145.5,"h":43.5,"circle":[[[21.8,21.8],12.8],[[47.2,21.8],12.8],[[72.8,21.8],12.8],[[98.2,21.8],12.8],[[123.8,21.8],12.8]],"pts":{"ㄱ":[21.8,21.8,"s"],"ㄴ":[123.8,21.8,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#7','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',3,'ox','auto','원 안에 그을 수 있는 가장 긴 선분은 지름이에요.',ARRAY['M3-2-u3-X17']::text[],true,'{"seq":7,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"원 안에 그을 수 있는 가장 긴 선분은 지름이에요.","answer":"O","reason_options":[{"t":"지름은 원의 중심을 지나 원의 가장 넓은 곳을 가로질러서","correct":true},{"t":"원 위의 두 점을 이은 선분은 길이가 모두 같아서","mis":"M3-2-u3-X17"}],"mis":"M3-2-u3-X17","explanation":["원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 것이 지름이에요.","지름은 원을 똑같이 둘로 나누고, 원 안에서 가장 긴 선분이에요.","맞는 말이에요(O)."],"variant_rule":{"alt":[{"stem":"지름은 원을 똑같이 둘로 나눠요.","answer":"O","reason_options":[{"t":"지름은 원의 중심을 지나 원의 가장 넓은 곳을 가로질러서","correct":true},{"t":"원 위의 두 점을 이은 선분은 길이가 모두 같아서","mis":"M3-2-u3-X17"}],"explanation":["원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 것이 지름이에요.","지름은 원을 똑같이 둘로 나누고, 원 안에서 가장 긴 선분이에요.","맞는 말이에요(O)."],"asset":null},{"stem":"원 위의 한 점에서 그은 선분 가운데 원의 중심을 지나는 선분이 가장 길어요.","answer":"O","reason_options":[{"t":"지름은 원의 중심을 지나 원의 가장 넓은 곳을 가로질러서","correct":true},{"t":"원 위의 두 점을 이은 선분은 길이가 모두 같아서","mis":"M3-2-u3-X17"}],"explanation":["원 위의 두 점을 이은 선분 가운데 원의 중심을 지나는 것이 지름이에요.","지름은 원을 똑같이 둘로 나누고, 원 안에서 가장 긴 선분이에요.","맞는 말이에요(O)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#8','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',4,'sa','auto','큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 8 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 8 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 8의 반 = 4(cm).","작은 원의 반지름: 4의 반 = 2(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 12 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 12의 반 = 6(cm).","작은 원의 반지름: 6의 반 = 3(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 16 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 16의 반 = 8(cm).","작은 원의 반지름: 8의 반 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#9','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C8',4,'sa','auto','직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 12 cm일 때 세로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 12 cm일 때 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가로에는 원의 지름이 2개, 세로에는 1개 들어 있어요.","지름 하나: 12의 반 = 6(cm).","세로는 지름 하나 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 16 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로에는 원의 지름이 2개 들어 있어요.","지름: 16의 반 = 8(cm).","반지름: 8의 반 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}},{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 20 cm일 때 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["가로에는 원의 지름이 2개, 세로에는 1개 들어 있어요.","지름 하나: 20의 반 = 10(cm).","세로는 지름 하나 — 10 cm예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L04_challenge#10','math',3,2,'u3','L04','g3_2_math_u3_L04_challenge','lesson_challenge','M3-2-u3-C5',4,'essay','teacher','반지름이 5 cm인 원 ㉠과 지름이 8 cm인 원 ㉡이 있어요. 어느 원이 더 큰지 쓰고, 그렇게 생각한 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C5","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 원 ㉠과 지름이 8 cm인 원 ㉡이 있어요. 어느 원이 더 큰지 쓰고, 그렇게 생각한 까닭을 지름과 반지름의 관계를 써서 설명해 보세요.","answer_guide":{"answer":"예: ㉠이 더 크다. 한 원에서 지름은 반지름의 2배이므로 ㉠의 지름은 5 × 2 = 10(cm)이다. ㉡의 지름은 8 cm이므로 지름을 견주면 10 cm가 8 cm보다 커서 ㉠이 더 크다.","scoring_points":["㉠이 더 크다고 답했는가","지름은 반지름의 2배라는 관계를 썼는가","같은 기준(지름 또는 반지름)으로 바꾸어 견주었는가"]},"explanation":["지름과 반지름이 섞여 있으면 한 가지로 바꿔요.","㉠의 지름 = 5 × 2 = 10 cm.","10 cm > 8 cm — ㉠이 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#1','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'mc','auto','컴퍼스로 원을 그릴 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u3-X12','M3-2-u3-X07']::text[],true,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스로 원을 그릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"원의 중심이 되는 점을 정해요","correct":true},{"t":"컴퍼스를 돌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"},{"t":"침을 원 위에 꽂아요","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그릴 때 침은 어디에 꽂나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X12"},{"t":"지름의 한 끝","mis":"M3-2-u3-X11"},{"t":"아무 곳이나","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null},{"stem":"컴퍼스로 원을 그리는 마지막 걸음은 무엇인가요?","options":[{"t":"침을 원의 중심에 꽂고 한 바퀴 돌려 그려요","correct":true},{"t":"원의 중심을 정해요","mis":"M3-2-u3-X12"},{"t":"컴퍼스를 반지름만큼 벌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#2','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'sa','auto','반지름이 3 cm인 원을 그리려면 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C6","difficulty":1,"kind":"sa","stem":"반지름이 3 cm인 원을 그리려면 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스를 벌린 길이가 원의 반지름이 돼요.","반지름이 3 cm이니까","3 cm 벌려요."],"variant_rule":{"alt":[{"stem":"컬링 경기장에 반지름이 4 cm인 원을 그리려고 해요. 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스를 벌린 길이가 원의 반지름이 돼요.","반지름이 4 cm이니까","4 cm 벌려요."],"asset":null},{"stem":"컴퍼스로 반지름 2 cm인 원을 그려요. 침과 연필 끝 사이를 몇 cm로 해야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스를 벌린 길이가 원의 반지름이 돼요.","반지름이 2 cm이니까","2 cm 벌려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#3','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',1,'mc','auto','컴퍼스의 침과 연필 끝 사이를 벌린 길이는 원의 무엇과 같나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X12','M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스의 침과 연필 끝 사이를 벌린 길이는 원의 무엇과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X11"},{"t":"원의 중심","mis":"M3-2-u3-X12"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「반지름」이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스를 벌린 길이를 2배 하면 그려지는 원의 무엇과 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X08"},{"t":"원의 중심","mis":"M3-2-u3-X12"},{"t":"컴퍼스의 길이","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「지름」이에요."],"asset":null},{"stem":"컴퍼스의 침이 꽂힌 점은 그려지는 원의 무엇인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「원의 중심」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
