INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#5','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'sa','auto','지름이 4 cm인 원을 그리려면 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"지름이 4 cm인 원을 그리려면 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 4 cm의 반 — 반지름은 2 cm예요.","2 cm 벌려요."],"variant_rule":{"alt":[{"stem":"지름 8 cm인 원 모양 무늬를 컴퍼스로 그리려고 해요. 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 8 cm의 반 — 반지름은 4 cm예요.","4 cm 벌려요."],"asset":null},{"stem":"컴퍼스로 지름이 6 cm인 원을 그려요. 침과 연필 끝 사이를 몇 cm로 해야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 6 cm의 반 — 반지름은 3 cm예요.","3 cm 벌려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#6','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'sa','auto','컴퍼스를 1 cm 벌려 그린 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"컴퍼스를 1 cm 벌려 그린 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["벌린 길이 1 cm가 반지름이에요.","지름은 반지름의 2배예요.","1 × 2 = 2(cm)예요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침과 연필 끝 사이를 3 cm로 하고 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["벌린 길이 3 cm가 반지름이에요.","지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."],"asset":null},{"stem":"4 cm 벌린 컴퍼스로 그린 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["벌린 길이 4 cm가 반지름이에요.","지름은 반지름의 2배예요.","4 × 2 = 8(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#7','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','컴퍼스로 원을 그리는 차례대로 놓은 것은 어느 것인가요? (㉠ 침과 연필 끝을 반지름만큼 벌려요 · ㉡ 원의 중심이 되는 점을 정해요 · ㉢ 침을 원의 중심에 꽂고 한 바퀴 돌려요)',ARRAY['M3-2-u3-X12']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"컴퍼스로 원을 그리는 차례대로 놓은 것은 어느 것인가요? (㉠ 침과 연필 끝을 반지름만큼 벌려요 · ㉡ 원의 중심이 되는 점을 정해요 · ㉢ 침을 원의 중심에 꽂고 한 바퀴 돌려요)","options":[{"t":"㉡ → ㉠ → ㉢","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"M3-2-u3-X12"},{"t":"㉠ → ㉢ → ㉡","mis":"M3-2-u3-X12"},{"t":"㉡ → ㉢ → ㉠","mis":"M3-2-u3-X12"}],"explanation":["먼저 원의 중심을 정해요.","다음에 반지름만큼 벌리고, 마지막에 침을 꽂고 돌려요.","차례는 ㉡ → ㉠ → ㉢이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그리는 차례대로 놓은 것은 어느 것인가요? (㉠ 원의 중심이 되는 점을 정해요 · ㉡ 침을 원의 중심에 꽂고 한 바퀴 돌려요 · ㉢ 침과 연필 끝을 반지름만큼 벌려요)","options":[{"t":"㉠ → ㉢ → ㉡","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"M3-2-u3-X12"},{"t":"㉡ → ㉠ → ㉢","mis":"M3-2-u3-X12"},{"t":"㉡ → ㉢ → ㉠","mis":"M3-2-u3-X12"}],"explanation":["먼저 원의 중심을 정해요.","다음에 반지름만큼 벌리고, 마지막에 침을 꽂고 돌려요.","차례는 ㉠ → ㉢ → ㉡이에요."],"asset":null},{"stem":"컴퍼스로 원을 그리는 차례대로 놓은 것은 어느 것인가요? (㉠ 침을 원의 중심에 꽂고 한 바퀴 돌려요 · ㉡ 침과 연필 끝을 반지름만큼 벌려요 · ㉢ 원의 중심이 되는 점을 정해요)","options":[{"t":"㉢ → ㉡ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"M3-2-u3-X12"},{"t":"㉠ → ㉢ → ㉡","mis":"M3-2-u3-X12"},{"t":"㉡ → ㉠ → ㉢","mis":"M3-2-u3-X12"}],"explanation":["먼저 원의 중심을 정해요.","다음에 반지름만큼 벌리고, 마지막에 침을 꽂고 돌려요.","차례는 ㉢ → ㉡ → ㉠이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#8','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','컴퍼스의 침을 자의 눈금 0에, 연필 끝을 눈금 3에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08']::text[],true,'{"seq":8,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"컴퍼스의 침을 자의 눈금 0에, 연필 끝을 눈금 3에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 3 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 6 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 12 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 3 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 3 cm(지름 6 cm)인 원이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침을 자의 눈금 0에, 연필 끝을 눈금 2에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 2 cm인 원","correct":true},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 2 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 2 cm(지름 4 cm)인 원이에요."],"asset":null},{"stem":"컴퍼스의 침을 자의 눈금 0에, 연필 끝을 눈금 4에 맞추었어요. 이 컴퍼스로 그린 원은 어떤 원인가요?","options":[{"t":"반지름이 4 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 8 cm인 원","mis":"M3-2-u3-X08"},{"t":"지름이 16 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["침에서 연필 끝까지 4 cm 벌렸어요.","벌린 길이가 반지름이에요.","반지름 4 cm(지름 8 cm)인 원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#9','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',2,'mc','auto','지름이 4 cm인 원을 그리려고 컴퍼스를 4 cm 벌려 그렸어요. 어떤 원이 그려지나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08','M3-2-u3-X12']::text[],true,'{"seq":9,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원을 그리려고 컴퍼스를 4 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 4 cm는 반지름이 돼요.","지름은 반지름의 2배 — 8 cm예요.","지름 4 cm인 원을 그리려면 2 cm만 벌려야 해요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원을 그리려고 컴퍼스를 6 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 12 cm인 원","correct":true},{"t":"지름이 6 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 6 cm는 반지름이 돼요.","지름은 반지름의 2배 — 12 cm예요.","지름 6 cm인 원을 그리려면 3 cm만 벌려야 해요."],"asset":null},{"stem":"지름이 8 cm인 원을 그리려고 컴퍼스를 8 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 16 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 8 cm는 반지름이 돼요.","지름은 반지름의 2배 — 16 cm예요.","지름 8 cm인 원을 그리려면 4 cm만 벌려야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_basic#10','math',3,2,'u3','L05','g3_2_math_u3_L05_basic','lesson_basic','M3-2-u3-C6',3,'ox','auto','지름이 6 cm인 원을 그리려면 컴퍼스를 6 cm 벌려야 해요.',ARRAY['M3-2-u3-X11']::text[],true,'{"seq":10,"concept":"M3-2-u3-C6","difficulty":3,"kind":"ox","stem":"지름이 6 cm인 원을 그리려면 컴퍼스를 6 cm 벌려야 해요.","answer":"X","reason_options":[{"t":"컴퍼스는 반지름만큼, 곧 3 cm 벌려야 해서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"mis":"M3-2-u3-X11","explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 6 cm의 반은 3 cm예요.","3 cm 벌려야 해요 — 이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원을 그리려면 컴퍼스를 10 cm 벌려야 해요.","answer":"X","reason_options":[{"t":"컴퍼스는 반지름만큼, 곧 5 cm 벌려야 해서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 10 cm의 반은 5 cm예요.","5 cm 벌려야 해요 — 이 말은 틀렸어요(X)."],"asset":null},{"stem":"지름이 12 cm인 원을 그리려면 컴퍼스를 12 cm 벌려야 해요.","answer":"X","reason_options":[{"t":"컴퍼스는 반지름만큼, 곧 6 cm 벌려야 해서","correct":true},{"t":"컴퍼스는 지름만큼 벌려서","mis":"M3-2-u3-X11"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 12 cm의 반은 6 cm예요.","6 cm 벌려야 해요 — 이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#1','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',2,'mc','auto','원 3개로 된 모양과 똑같이 그리려고 해요. 먼저 무엇을 확인해야 하나요?',ARRAY['M3-2-u3-X12']::text[],true,'{"seq":1,"concept":"M3-2-u3-C6","difficulty":2,"kind":"mc","stem":"원 3개로 된 모양과 똑같이 그리려고 해요. 먼저 무엇을 확인해야 하나요?","options":[{"t":"원마다 원의 중심과 반지름","correct":true},{"t":"원의 색깔","mis":"M3-2-u3-X12"},{"t":"원을 그린 순서만","mis":"M3-2-u3-X12"},{"t":"종이의 크기","mis":"M3-2-u3-X12"}],"explanation":["원을 그리려면 원의 중심(침 꽂을 곳)과 반지름(벌릴 길이)이 필요해요.","중심이 같으면 침은 같은 곳에, 반지름만 바꾸어 그려요.","답은 「원마다 원의 중심과 반지름」이에요."],"variant_rule":{"alt":[{"stem":"컬링 경기장처럼 중심이 같은 원 여러 개를 그리려고 해요. 원마다 바꾸어야 하는 것은 무엇인가요?","options":[{"t":"컴퍼스를 벌린 길이","correct":true},{"t":"침을 꽂는 곳","mis":"M3-2-u3-X03"},{"t":"연필의 색","mis":"M3-2-u3-X12"},{"t":"종이의 방향","mis":"M3-2-u3-X12"}],"explanation":["원을 그리려면 원의 중심(침 꽂을 곳)과 반지름(벌릴 길이)이 필요해요.","중심이 같으면 침은 같은 곳에, 반지름만 바꾸어 그려요.","답은 「컴퍼스를 벌린 길이」예요."],"asset":null},{"stem":"원 4개로 된 모양과 똑같이 그리려고 해요. 먼저 무엇을 확인해야 하나요?","options":[{"t":"원마다 원의 중심과 반지름","correct":true},{"t":"원의 색깔","mis":"M3-2-u3-X12"},{"t":"원을 그린 순서만","mis":"M3-2-u3-X12"},{"t":"종이의 크기","mis":"M3-2-u3-X12"}],"explanation":["원을 그리려면 원의 중심(침 꽂을 곳)과 반지름(벌릴 길이)이 필요해요.","중심이 같으면 침은 같은 곳에, 반지름만 바꾸어 그려요.","답은 「원마다 원의 중심과 반지름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#2','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',2,'error','auto','컴퍼스로 원을 그리는 방법을 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X16']::text[],true,'{"seq":2,"concept":"M3-2-u3-C6","difficulty":2,"kind":"error","stem":"컴퍼스로 원을 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「지름이 4 cm인 원은 컴퍼스를 4 cm 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"가람 — 「먼저 원의 중심을 정해.」","mis":"M3-2-u3-X16"},{"t":"하늘 — 「침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"도윤 — 「반지름이 4 cm면 4 cm 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 4 cm인 원은 2 cm 벌려야 해요.","민호의 말이 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 컴퍼스로 원을 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"가람 — 「지름이 6 cm인 원은 컴퍼스를 6 cm 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"하늘 — 「먼저 원의 중심을 정해.」","mis":"M3-2-u3-X16"},{"t":"도윤 — 「침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"나래 — 「반지름이 6 cm면 6 cm 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 6 cm인 원은 3 cm 벌려야 해요.","가람의 말이 잘못이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 컴퍼스로 원을 그리는 방법을 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「지름이 8 cm인 원은 컴퍼스를 8 cm 벌려 그려.」","correct":true,"mis_target":"M3-2-u3-X11"},{"t":"도윤 — 「먼저 원의 중심을 정해.」","mis":"M3-2-u3-X16"},{"t":"나래 — 「침은 원의 중심에 꽂아.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「반지름이 8 cm면 8 cm 벌려.」","mis":"M3-2-u3-X16"}],"explanation":["컴퍼스를 벌린 길이는 반지름이에요.","지름 8 cm인 원은 4 cm 벌려야 해요.","하늘의 말이 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#3','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'mc','auto','이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],true,'{"seq":3,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"2군데","correct":true},{"t":"3군데","mis":"M3-2-u3-X15"},{"t":"1군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 3개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 2군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[45,45],30],[[45,45],15],[[105,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 4개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 3군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[37.5,45],22.5],[[82.5,45],22.5],[[127.5,45],22.5],[[82.5,45],12.0]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"1군데","correct":true},{"t":"3군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 3개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 1군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[75,45],37.5],[[75,45],22.5],[[75,45],9.0]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#4','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'sa','auto','컴퍼스로 지름이 6 cm인 원과 반지름이 4 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"컴퍼스로 지름이 6 cm인 원과 반지름이 4 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["컴퍼스는 반지름만큼 벌려요.","지름 6 cm인 원: 3 cm, 반지름 4 cm인 원: 4 cm.","3 + 4 = 7(cm)예요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 지름이 8 cm인 원과 반지름이 2 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["컴퍼스는 반지름만큼 벌려요.","지름 8 cm인 원: 4 cm, 반지름 2 cm인 원: 2 cm.","4 + 2 = 6(cm)예요."],"asset":null},{"stem":"컴퍼스로 지름이 10 cm인 원과 반지름이 3 cm인 원을 차례로 그렸어요. 두 번 벌린 길이를 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["컴퍼스는 반지름만큼 벌려요.","지름 10 cm인 원: 5 cm, 반지름 3 cm인 원: 3 cm.","5 + 3 = 8(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#5','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'mc','auto','컴퍼스를 2 cm 벌려 그린 원과 크기가 같은 원은 어느 것인가요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08']::text[],true,'{"seq":5,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"컴퍼스를 2 cm 벌려 그린 원과 크기가 같은 원은 어느 것인가요?","options":[{"t":"지름이 4 cm인 원","correct":true},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"반지름이 1 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["2 cm 벌려 그린 원의 반지름은 2 cm예요.","지름으로 바꾸면 4 cm예요.","지름이 4 cm인 원과 크기가 같아요."],"variant_rule":{"alt":[{"stem":"컴퍼스를 3 cm 벌려 그린 원과 크기가 같은 원은 어느 것인가요?","options":[{"t":"지름이 6 cm인 원","correct":true},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 6 cm인 원","mis":"M3-2-u3-X08"},{"t":"반지름이 4 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["3 cm 벌려 그린 원의 반지름은 3 cm예요.","지름으로 바꾸면 6 cm예요.","지름이 6 cm인 원과 크기가 같아요."],"asset":null},{"stem":"컴퍼스를 4 cm 벌려 그린 원과 크기가 같은 원은 어느 것인가요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"반지름이 8 cm인 원","mis":"M3-2-u3-X08"},{"t":"반지름이 2 cm인 원","mis":"M3-2-u3-X08"}],"explanation":["4 cm 벌려 그린 원의 반지름은 4 cm예요.","지름으로 바꾸면 8 cm예요.","지름이 8 cm인 원과 크기가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#6','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'sa','auto','같은 점 ㅇ에 침을 꽂고 컴퍼스를 2 cm, 4 cm 벌려 원 두 개를 그렸어요. 큰 원의 지름은 작은 원의 지름보다 몇 cm 더 긴가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C6","difficulty":3,"kind":"sa","stem":"같은 점 ㅇ에 침을 꽂고 컴퍼스를 2 cm, 4 cm 벌려 원 두 개를 그렸어요. 큰 원의 지름은 작은 원의 지름보다 몇 cm 더 긴가요? 숫자로 쓰세요.","answer":["4"],"explanation":["지름은 벌린 길이(반지름)의 2배예요.","작은 원 지름 4 cm, 큰 원 지름 8 cm.","8 − 4 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":135,"pts":{"ㅇ":[67.5,67.5,"n"]},"circle":[[[67.5,67.5],24.0],[[67.5,67.5],48.0]]}],"tag":false},"variant_rule":{"alt":[{"stem":"같은 점 ㅇ에 침을 꽂고 컴퍼스를 1 cm, 3 cm 벌려 원 두 개를 그렸어요. 큰 원의 지름은 작은 원의 지름보다 몇 cm 더 긴가요? 숫자로 쓰세요.","answer":["4"],"explanation":["지름은 벌린 길이(반지름)의 2배예요.","작은 원 지름 2 cm, 큰 원 지름 6 cm.","6 − 2 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":135,"pts":{"ㅇ":[67.5,67.5,"n"]},"circle":[[[67.5,67.5],12.0],[[67.5,67.5],36.00000000000001]]}],"tag":false}},{"stem":"같은 점 ㅇ에 침을 꽂고 컴퍼스를 3 cm, 5 cm 벌려 원 두 개를 그렸어요. 큰 원의 지름은 작은 원의 지름보다 몇 cm 더 긴가요? 숫자로 쓰세요.","answer":["4"],"explanation":["지름은 벌린 길이(반지름)의 2배예요.","작은 원 지름 6 cm, 큰 원 지름 10 cm.","10 − 6 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":135,"pts":{"ㅇ":[67.5,67.5,"n"]},"circle":[[[67.5,67.5],36.00000000000001],[[67.5,67.5],60.0]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#7','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',3,'ox','auto','컴퍼스로 원을 그릴 때 침을 꽂은 점은 원 위의 점이에요.',ARRAY['M3-2-u3-X12']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":3,"kind":"ox","stem":"컴퍼스로 원을 그릴 때 침을 꽂은 점은 원 위의 점이에요.","answer":"X","reason_options":[{"t":"침을 꽂은 점은 원의 중심이라서","correct":true},{"t":"침도 원 위를 따라 움직여서","mis":"M3-2-u3-X12"}],"mis":"M3-2-u3-X12","explanation":["컴퍼스의 침은 원의 중심에 꽂고 움직이지 않아요.","원 위를 도는 것은 연필 끝이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침은 그릴 원 위의 한 점에 꽂아요.","answer":"X","reason_options":[{"t":"침을 꽂은 점은 원의 중심이라서","correct":true},{"t":"침도 원 위를 따라 움직여서","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂고 움직이지 않아요.","원 위를 도는 것은 연필 끝이에요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"컴퍼스의 연필 끝이 꽂힌 점이 원의 중심이에요.","answer":"X","reason_options":[{"t":"침을 꽂은 점은 원의 중심이라서","correct":true},{"t":"침도 원 위를 따라 움직여서","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스의 침은 원의 중심에 꽂고 움직이지 않아요.","원 위를 도는 것은 연필 끝이에요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#8','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C8',4,'sa','auto','반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그리려고 해요. 첫째 원을 그린 다음, 둘째 원의 중심은 첫째 원의 중심에서 몇 cm 떨어진 곳에 정해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그리려고 해요. 첫째 원을 그린 다음, 둘째 원의 중심은 첫째 원의 중심에서 몇 cm 떨어진 곳에 정해야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["맞닿은 두 원의 중심 사이에는 반지름이 2개 들어 있어요.","첫째 원의 반지름 + 둘째 원의 반지름이에요.","2 + 2 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그리려고 해요. 첫째 원을 그린 다음, 둘째 원의 중심은 첫째 원의 중심에서 몇 cm 떨어진 곳에 정해야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["맞닿은 두 원의 중심 사이에는 반지름이 2개 들어 있어요.","첫째 원의 반지름 + 둘째 원의 반지름이에요.","3 + 3 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]]}],"tag":false}},{"stem":"반지름이 4 cm인 원 3개를 맞닿게 한 줄로 그리려고 해요. 첫째 원을 그린 다음, 둘째 원의 중심은 첫째 원의 중심에서 몇 cm 떨어진 곳에 정해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["맞닿은 두 원의 중심 사이에는 반지름이 2개 들어 있어요.","첫째 원의 반지름 + 둘째 원의 반지름이에요.","4 + 4 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#9','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C8',4,'sa','auto','반지름이 5 cm인 원 위에 반지름이 3 cm인 원을 맞닿게 올려 눈사람을 그렸어요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"반지름이 5 cm인 원 위에 반지름이 3 cm인 원을 맞닿게 올려 눈사람을 그렸어요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㄱㄴ은 작은 원의 반지름과 큰 원의 반지름을 이은 것이에요.","작은 원 3 cm + 큰 원 5 cm.","3 + 5 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":195,"circle":[[[52.5,38.2],20.25],[[52.5,92.2],33.75]],"pts":{"ㄱ":[52.5,38.2,"e"],"ㄴ":[52.5,92.2,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 위에 반지름이 4 cm인 원을 맞닿게 올려 눈사람을 그렸어요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㄱㄴ은 작은 원의 반지름과 큰 원의 반지름을 이은 것이에요.","작은 원 4 cm + 큰 원 6 cm.","4 + 6 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":195,"circle":[[[52.5,45.0],27.0],[[52.5,112.5],40.5]],"pts":{"ㄱ":[52.5,45.0,"e"],"ㄴ":[52.5,112.5,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"반지름이 4 cm인 원 위에 반지름이 2 cm인 원을 맞닿게 올려 눈사람을 그렸어요. 두 원의 중심 ㄱ과 ㄴ 사이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㄱㄴ은 작은 원의 반지름과 큰 원의 반지름을 이은 것이에요.","작은 원 2 cm + 큰 원 4 cm.","2 + 4 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":105,"h":195,"circle":[[[52.5,31.5],13.5],[[52.5,72.0],27.0]],"pts":{"ㄱ":[52.5,31.5,"e"],"ㄴ":[52.5,72.0,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L05_challenge#10','math',3,2,'u3','L05','g3_2_math_u3_L05_challenge','lesson_challenge','M3-2-u3-C6',4,'essay','teacher','지름이 8 cm인 원을 컴퍼스로 그리는 방법을 차례대로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C6","difficulty":4,"kind":"essay","stem":"지름이 8 cm인 원을 컴퍼스로 그리는 방법을 차례대로 써 보세요.","answer_guide":{"answer":"예: ① 종이에 원의 중심이 될 점 ㅇ을 찍는다. ② 지름 8 cm의 반인 4 cm만큼 자에 대어 컴퍼스의 침과 연필 끝을 벌린다. ③ 침을 점 ㅇ에 꽂고 연필 쪽을 한 바퀴 돌려 원을 그린다.","scoring_points":["원의 중심을 먼저 정했는가","지름의 반인 4 cm만큼 벌린다고 썼는가","침을 중심에 꽂고 돌려 그린다고 썼는가"]},"explanation":["① 중심 정하기.","② 반지름(지름의 반 = 4 cm)만큼 벌리기.","③ 침을 중심에 꽂고 돌리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#1','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'mc','auto','모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":1,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸, 2칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"2칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 1, 2칸.","규칙: 반지름이 1칸, 2칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸씩 커져요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"2칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 3, 4칸.","규칙: 반지름이 1칸씩 커져요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"모두 1칸이에요","correct":true},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"2칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 1, 1, 1칸.","규칙: 반지름이 모두 1칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, m