INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#3','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'sa','auto','이 규칙대로 원을 하나 더 그리면, 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C7","difficulty":1,"kind":"sa","stem":"이 규칙대로 원을 하나 더 그리면, 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름을 차례로 써요 — 1, 2, 1, 2칸.","규칙: 반지름이 1칸, 2칸이 되풀이돼요.","다섯째 원의 반지름은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 규칙대로 원을 하나 더 그리면, 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["반지름을 차례로 써요 — 1, 2, 3, 4칸.","규칙: 반지름이 1칸씩 커져요.","다섯째 원의 반지름은 5칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 규칙대로 원을 하나 더 그리면, 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["반지름을 차례로 써요 — 1, 2, 3, 1칸.","규칙: 반지름이 1칸, 2칸, 3칸이 되풀이돼요.","다섯째 원의 반지름은 2칸이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#4','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',1,'mc','auto','반지름이 모눈 2칸인 원의 지름은 모눈 몇 칸인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":4,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"반지름이 모눈 2칸인 원의 지름은 모눈 몇 칸인가요?","options":[{"t":"4칸","correct":true},{"t":"2칸","mis":"M3-2-u3-X09"},{"t":"3칸","mis":"M3-2-u3-X09"},{"t":"8칸","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름의 2배예요.","2 × 2 = 4.","지름은 4칸이에요."],"variant_rule":{"alt":[{"stem":"모눈 위에 반지름이 3칸인 원을 그렸어요. 지름은 몇 칸인가요?","options":[{"t":"6칸","correct":true},{"t":"3칸","mis":"M3-2-u3-X09"},{"t":"4칸","mis":"M3-2-u3-X09"},{"t":"12칸","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름의 2배예요.","3 × 2 = 6.","지름은 6칸이에요."],"asset":null},{"stem":"반지름 1칸인 원을 그리면 원의 왼쪽 끝에서 오른쪽 끝까지 몇 칸인가요?","options":[{"t":"2칸","correct":true},{"t":"1칸","mis":"M3-2-u3-X09"},{"t":"4칸","mis":"M3-2-u3-X08"},{"t":"3칸","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름의 2배예요.","1 × 2 = 2.","지름은 2칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#5','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'sa','auto','이 규칙대로 원을 계속 그리면 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙대로 원을 계속 그리면 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 1칸, 2칸이 되풀이돼요.","차례로 이어 쓰면 1, 2, 1, 2, 1칸.","다섯째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","차례로 이어 쓰면 1, 2, 3, 1, 2, 3, 1칸.","일곱째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}},{"stem":"이 규칙대로 원을 계속 그리면 여섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 3칸, 2칸, 1칸이 되풀이돼요.","차례로 이어 쓰면 3, 2, 1, 3, 2, 1칸.","여섯째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[60,60],45],[[135,60],30],[[180,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#6','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'mc','auto','반지름은 그대로 두고 원의 중심만 옮겨 가며 그렸어요. 원의 크기는 어떻게 되나요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":6,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"반지름은 그대로 두고 원의 중심만 옮겨 가며 그렸어요. 원의 크기는 어떻게 되나요?","options":[{"t":"모두 같아요","correct":true},{"t":"점점 커져요","mis":"M3-2-u3-X14"},{"t":"점점 작아져요","mis":"M3-2-u3-X14"},{"t":"알 수 없어요","mis":"M3-2-u3-X14"}],"explanation":["원의 크기는 반지름이 정해요.","원의 중심은 원이 놓이는 자리를 정해요.","답은 「모두 같아요」예요."],"variant_rule":{"alt":[{"stem":"원의 중심은 그대로 두고 반지름만 1칸씩 늘려 그렸어요. 어떤 무늬가 되나요?","options":[{"t":"중심이 같은 원이 점점 커지는 무늬","correct":true},{"t":"같은 크기의 원이 한 줄로 늘어선 무늬","mis":"M3-2-u3-X13"},{"t":"원이 점점 작아지는 무늬","mis":"M3-2-u3-X14"},{"t":"원이 오른쪽으로 옮겨 가는 무늬","mis":"M3-2-u3-X13"}],"explanation":["원의 크기는 반지름이 정해요.","원의 중심은 원이 놓이는 자리를 정해요.","답은 「중심이 같은 원이 점점 커지는 무늬」예요."],"asset":null},{"stem":"원 무늬에서 원의 크기를 바꾸려면 무엇을 바꾸어야 하나요?","options":[{"t":"반지름","correct":true},{"t":"원의 중심의 자리","mis":"M3-2-u3-X13"},{"t":"원을 그리는 순서","mis":"M3-2-u3-X12"},{"t":"모눈의 색","mis":"M3-2-u3-X12"}],"explanation":["원의 크기는 반지름이 정해요.","원의 중심은 원이 놓이는 자리를 정해요.","답은 「반지름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#7','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'sa','auto','원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["2"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","2칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]],"pts":{"①":[30,30,"n"],"②":[60,30,"n"],"③":[90,30,"n"],"④":[120,30,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["3"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","3칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":195,"h":60,"grid":15,"circle":[[[30,30],15],[[75,30],15],[[120,30],15],[[165,30],15]],"pts":{"①":[30,30,"n"],"②":[75,30,"n"],"③":[120,30,"n"],"④":[165,30,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["3"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","3칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]],"pts":{"①":[30,45,"n"],"②":[75,45,"n"],"③":[120,45,"n"],"④":[165,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#8','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'mc','auto','원을 화면에서 그리면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u3-X12','M3-2-u3-X01']::text[],true,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"원을 화면에서 그리면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쉽게 그리고 지울 수 있어요","correct":true},{"t":"원의 중심이 필요 없어요","mis":"M3-2-u3-X12"},{"t":"반지름을 정하지 않아도 돼요","mis":"M3-2-u3-X12"},{"t":"원이 아닌 모양이 돼요","mis":"M3-2-u3-X01"}],"explanation":["원은 원의 중심과 반지름이 정해지면 그려져요.","화면에서는 정확하게, 쉽게 그리고 지울 수 있어요.","답은 「쉽게 그리고 지울 수 있어요」예요."],"variant_rule":{"alt":[{"stem":"화면에서 원을 그릴 때 꼭 정해야 하는 두 가지는 무엇인가요?","options":[{"t":"원의 중심과 반지름","correct":true},{"t":"원의 색과 굵기","mis":"M3-2-u3-X12"},{"t":"종이와 연필","mis":"M3-2-u3-X12"},{"t":"컴퍼스와 자","mis":"M3-2-u3-X12"}],"explanation":["원은 원의 중심과 반지름이 정해지면 그려져요.","화면에서는 정확하게, 쉽게 그리고 지울 수 있어요.","답은 「원의 중심과 반지름」이에요."],"asset":null},{"stem":"규칙에 따라 원 무늬를 그리기 전에 먼저 정할 것은 무엇인가요?","options":[{"t":"원의 중심을 옮기는 규칙과 반지름의 규칙","correct":true},{"t":"원의 색깔만","mis":"M3-2-u3-X12"},{"t":"원의 개수만","mis":"M3-2-u3-X12"},{"t":"종이의 크기만","mis":"M3-2-u3-X12"}],"explanation":["원은 원의 중심과 반지름이 정해지면 그려져요.","화면에서는 정확하게, 쉽게 그리고 지울 수 있어요.","답은 「원의 중심을 옮기는 규칙과 반지름의 규칙」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#9','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',2,'sa','auto','둘째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"둘째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["둘째 원의 반지름을 모눈으로 세면 2칸이에요.","지름은 반지름의 2배예요.","2 × 2 = 4칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"셋째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["셋째 원의 반지름을 모눈으로 세면 3칸이에요.","지름은 반지름의 2배예요.","3 × 2 = 6칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]]}],"tag":false}},{"stem":"셋째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["셋째 원의 반지름을 모눈으로 세면 3칸이에요.","지름은 반지름의 2배예요.","3 × 2 = 6칸이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_basic#10','math',3,2,'u3','L06','g3_2_math_u3_L06_basic','lesson_basic','M3-2-u3-C7',3,'ox','auto','이 무늬에서 원의 중심은 모두 같은 가로줄 위에 있어요.',ARRAY['M3-2-u3-X13']::text[],true,'{"seq":10,"concept":"M3-2-u3-C7","difficulty":3,"kind":"ox","stem":"이 무늬에서 원의 중심은 모두 같은 가로줄 위에 있어요.","answer":"O","reason_options":[{"t":"중심이 모두 같은 줄에서 오른쪽으로만 옮겨 가서","correct":true},{"t":"중심이 위아래로도 옮겨 가서","mis":"M3-2-u3-X13"}],"mis":"M3-2-u3-X13","explanation":["원의 중심 ①, ②, ③, ④를 이어 봐요.","모두 같은 가로줄 위에 있어요.","맞는 말이에요(O)."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]],"pts":{"①":[30,45,"n"],"②":[75,45,"n"],"③":[120,45,"n"],"④":[165,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 무늬에서 원의 중심은 모두 같은 가로줄 위에 있어요.","answer":"X","reason_options":[{"t":"중심이 오른쪽으로 옮겨 가면서 위쪽으로도 올라가서","correct":true},{"t":"중심이 오른쪽으로만 옮겨 가서","mis":"M3-2-u3-X13"}],"explanation":["원의 중심 ①, ②, ③, ④를 이어 봐요.","오른쪽으로 2칸, 위쪽으로 2칸씩 옮겨 가요.","같은 가로줄 위에 있지 않아요(X)."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[30,120],15],[[60,90],15],[[90,60],15],[[120,30],15]],"pts":{"①":[30,120,"n"],"②":[60,90,"n"],"③":[90,60,"n"],"④":[120,30,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 무늬에서 원의 중심은 모두 같은 가로줄 위에 있어요.","answer":"O","reason_options":[{"t":"중심이 모두 같은 줄에서 오른쪽으로만 옮겨 가서","correct":true},{"t":"중심이 위아래로도 옮겨 가서","mis":"M3-2-u3-X13"}],"explanation":["원의 중심 ①, ②, ③, ④를 이어 봐요.","모두 같은 가로줄 위에 있어요.","맞는 말이에요(O)."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]],"pts":{"①":[30,30,"n"],"②":[60,30,"n"],"③":[90,30,"n"],"④":[120,30,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#1','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',2,'mc','auto','모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":1,"concept":"M3-2-u3-C7","difficulty":2,"kind":"mc","stem":"모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"2칸, 1칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 2, 1, 2, 1칸.","규칙: 반지름이 2칸, 1칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸, 2칸, 3칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 3, 1, 2칸.","규칙: 반지름이 1칸, 2칸, 3칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":300,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15],[[255,60],30]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"3칸, 2칸, 1칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 3, 2, 1, 3, 2칸.","규칙: 반지름이 3칸, 2칸, 1칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":360,"h":120,"grid":15,"circle":[[[60,60],45],[[135,60],30],[[180,60],15],[[240,60],45],[[315,60],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#2','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',2,'sa','auto','이 규칙대로 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙대로 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","차례로 이어 쓰면 1, 2, 3, 1, 2, 3, 1칸.","일곱째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원을 계속 그리면 여섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 3칸, 2칸, 1칸이 되풀이돼요.","차례로 이어 쓰면 3, 2, 1, 3, 2, 1칸.","여섯째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[60,60],45],[[135,60],30],[[180,60],15]]}],"tag":false}},{"stem":"이 규칙대로 원을 계속 그리면 여덟째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 2칸, 1칸이 되풀이돼요.","차례로 이어 쓰면 2, 1, 2, 1, 2, 1, 2, 1칸.","여덟째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#3','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','이 규칙대로 원 4개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"이 규칙대로 원 4개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름: 1, 2, 1, 2칸.","가로에는 원마다 지름이 하나씩 놓여요 — 2, 4, 2, 4칸.","2 + 4 + 2 + 4 = 12칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원 6개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["반지름: 1, 2, 1, 2, 1, 2칸.","가로에는 원마다 지름이 하나씩 놓여요 — 2, 4, 2, 4, 2, 4칸.","2 + 4 + 2 + 4 + 2 + 4 = 18칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}},{"stem":"이 규칙대로 원 3개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름: 1, 2, 3칸.","가로에는 원마다 지름이 하나씩 놓여요 — 2, 4, 6칸.","2 + 4 + 6 = 12칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#4','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["첫째 원은 반지름, 사이의 원은 지름, 넷째 원은 반지름만큼 들어 있어요.","1 + 4 + 2 + 2칸.","모두 9칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 셋째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["첫째 원은 반지름, 사이의 원은 지름, 셋째 원은 반지름만큼 들어 있어요.","1 + 4 + 3칸.","모두 8칸이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false}},{"stem":"원이 맞닿게 이어진 무늬예요. 둘째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["둘째 원은 반지름, 사이의 원은 지름, 다섯째 원은 반지름만큼 들어 있어요.","1 + 4 + 2 + 2칸.","모두 9칸이에요."],"asset":{"type":"geo","items":[{"w":270,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15],[[225,45],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#5','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'mc','auto','이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u3-X14','M3-2-u3-X13']::text[],true,'{"seq":5,"concept":"M3-2-u3-C7","difficulty":3,"kind":"mc","stem":"이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"반지름은 그대로 두고, 원의 중심을 오른쪽으로 2칸, 위쪽으로 2칸씩 옮겼어요","correct":true},{"t":"반지름을 1칸씩 늘리고, 원의 중심을 오른쪽으로 옮겼어요","mis":"M3-2-u3-X14"},{"t":"반지름은 그대로 두고, 원의 중심을 오른쪽으로만 옮겼어요","mis":"M3-2-u3-X13"},{"t":"원의 중심은 그대로 두고 반지름만 바꾸었어요","mis":"M3-2-u3-X13"}],"explanation":["반지름이 어떻게 바뀌는지 먼저 보아요.","다음에 원의 중심이 어디로 옮겨 가는지 보아요.","규칙: 반지름은 그대로 두고, 원의 중심을 오른쪽으로 2칸, 위쪽으로 2칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":150,"h":150,"grid":15,"circle":[[[30,120],15],[[60,90],15],[[90,60],15],[[120,30],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"원의 중심은 그대로 두고, 반지름을 1칸씩 늘렸어요","correct":true},{"t":"반지름은 그대로 두고 원의 중심을 옮겼어요","mis":"M3-2-u3-X13"},{"t":"원의 중심을 오른쪽으로 1칸씩 옮겼어요","mis":"M3-2-u3-X13"},{"t":"반지름을 1칸, 2칸으로 되풀이했어요","mis":"M3-2-u3-X14"}],"explanation":["반지름이 어떻게 바뀌는지 먼저 보아요.","다음에 원의 중심이 어디로 옮겨 가는지 보아요.","규칙: 원의 중심은 그대로 두고, 반지름을 1칸씩 늘렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],15],[[60,60],30],[[60,60],45]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 원 무늬를 만든 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"반지름을 1칸, 2칸으로 되풀이하고, 원이 맞닿게 중심을 오른쪽으로 옮겼어요","correct":true},{"t":"반지름을 1칸씩 늘렸어요","mis":"M3-2-u3-X14"},{"t":"반지름은 모두 같고 중심만 옮겼어요","mis":"M3-2-u3-X14"},{"t":"원의 중심은 그대로 두고 반지름만 바꾸었어요","mis":"M3-2-u3-X13"}],"explanation":["반지름이 어떻게 바뀌는지 먼저 보아요.","다음에 원의 중심이 어디로 옮겨 가는지 보아요.","규칙: 반지름을 1칸, 2칸으로 되풀이하고, 원이 맞닿게 중심을 오른쪽으로 옮겼어요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#6','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'sa','auto','중심이 같은 원을 반지름이 1칸씩 커지도록 그리고 있어요(가장 작은 원의 반지름은 1칸). 다섯째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"중심이 같은 원을 반지름이 1칸씩 커지도록 그리고 있어요(가장 작은 원의 반지름은 1칸). 다섯째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["반지름: 1칸, 2칸, 3칸 … — 다섯째 원은 5칸이에요.","지름은 반지름의 2배예요.","5 × 2 = 10칸이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],15],[[60,60],30],[[60,60],45]]}],"tag":false},"variant_rule":{"alt":[{"stem":"중심이 같은 원을 반지름이 1칸씩 커지도록 그리고 있어요(가장 작은 원의 반지름은 1칸). 넷째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["반지름: 1칸, 2칸, 3칸 … — 넷째 원은 4칸이에요.","지름은 반지름의 2배예요.","4 × 2 = 8칸이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],15],[[60,60],30],[[60,60],45]]}],"tag":false}},{"stem":"중심이 같은 원을 반지름이 1칸씩 커지도록 그리고 있어요(가장 작은 원의 반지름은 1칸). 여섯째 원의 지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름: 1칸, 2칸, 3칸 … — 여섯째 원은 6칸이에요.","지름은 반지름의 2배예요.","6 × 2 = 12칸이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"grid":15,"circle":[[[60,60],15],[[60,60],30],[[60,60],45]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#7','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',3,'error','auto','이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X14','M3-2-u3-X16']::text[],true,'{"seq":7,"concept":"M3-2-u3-C7","difficulty":3,"kind":"error","stem":"이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「다섯째 원의 반지름은 2칸이야.」","correct":true,"mis_target":"M3-2-u3-X14"},{"t":"하랑 — 「반지름이 1칸, 2칸이 되풀이돼.」","mis":"M3-2-u3-X16"},{"t":"지아 — 「원의 중심은 오른쪽으로 옮겨 가.」","mis":"M3-2-u3-X16"},{"t":"민호 — 「원은 서로 맞닿아 있어.」","mis":"M3-2-u3-X16"}],"explanation":["반지름 규칙: 1칸, 2칸이 되풀이돼요.","다섯째 원의 반지름은 1칸이에요.","은우의 말이 잘못이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「다섯째 원의 반지름은 1칸이야.」","correct":true,"mis_target":"M3-2-u3-X14"},{"t":"지아 — 「반지름이 1칸, 2칸, 3칸이 되풀이돼.」","mis":"M3-2-u3-X16"},{"t":"민호 — 「원의 중심은 오른쪽으로 옮겨 가.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「원은 서로 맞닿아 있어.」","mis":"M3-2-u3-X16"}],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","다섯째 원의 반지름은 2칸이에요.","하랑의 말이 잘못이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 원 무늬의 규칙을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「다섯째 원의 반지름은 1칸이야.」","correct":true,"mis_target":"M3-2-u3-X14"},{"t":"민호 — 「반지름이 2칸, 1칸이 되풀이돼.」","mis":"M3-2-u3-X16"},{"t":"가람 — 「원의 중심은 오른쪽으로 옮겨 가.」","mis":"M3-2-u3-X16"},{"t":"하늘 — 「원은 서로 맞닿아 있어.」","mis":"M3-2-u3-X16"}],"explanation":["반지름 규칙: 2칸, 1칸이 되풀이돼요.","다섯째 원의 반지름은 2칸이에요.","지아의 말이 잘못이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#8','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'sa','auto','이 규칙대로 원을 10개 그렸어요. 반지름이 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙대로 원을 10개 그렸어요. 반지름이 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["반지름 규칙: 1칸, 2칸이 되풀이돼요.","10개를 차례로 쓰면 1, 2, 1, 2, 1, 2, 1, 2, 1, 2.","반지름 2칸인 원은 5개예요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 규칙대로 원을 10개 그렸어요. 반지름이 2칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","10개를 차례로 쓰면 1, 2, 3, 1, 2, 3, 1, 2, 3, 1.","반지름 2칸인 원은 3개예요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}},{"stem":"이 규칙대로 원을 9개 그렸어요. 반지름이 3칸인 원은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","9개를 차례로 쓰면 1, 2, 3, 1, 2, 3, 1, 2, 3.","반지름 3칸인 원은 3개예요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#9','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'sa','auto','이 규칙대로 원을 맞닿게 이어 그려요. 넷째 원의 중심에서 일곱째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u3-C7","difficulty":4,"kind":"sa","stem":"이 규칙대로 원을 맞닿게 이어 그려요. 넷째 원의 중심에서 일곱째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["반지름을 이어 쓰면 1, 2, 1, 2, 1, 2, 1칸.","넷째 원은 반지름, 사이 원은 지름, 일곱째 원은 반지름: 2 + 2 + 4 + 1.","9칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원을 맞닿게 이어 그려요. 둘째 원의 중심에서 여섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["반지름을 이어 쓰면 1, 2, 3, 1, 2, 3칸.","둘째 원은 반지름, 사이 원은 지름, 여섯째 원은 반지름: 2 + 6 + 2 + 4 + 3.","17칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}},{"stem":"이 규칙대로 원을 맞닿게 이어 그려요. 셋째 원의 중심에서 여섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["반지름을 이어 쓰면 2, 1, 2, 1, 2, 1칸.","셋째 원은 반지름, 사이 원은 지름, 여섯째 원은 반지름: 2 + 2 + 4 + 1.","9칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_L06_challenge#10','math',3,2,'u3','L06','g3_2_math_u3_L06_challenge','lesson_challenge','M3-2-u3-C7',4,'essay','teacher','모눈종이에 원 4개로 나만의 무늬를 그리려고 해요. 원의 중심을 옮기는 규칙과 반지름의 규칙을 정해 쓰고, 넷째 원의 반지름이 몇 칸인지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u3-C7","difficulty":4,"kind":"essay","stem":"모눈종이에 원 4개로 나만의 무늬를 그리려고 해요. 원의 중심을 옮기는 규칙과 반지름의 규칙을 정해 쓰고, 넷째 원의 반지름이 몇 칸인지 써 보세요.","answer_guide":{"answer":"예: 가운데에 반지름 3칸인 원을 그리고, 원의 중심을 오른쪽으로 옮기면서 반지름을 3칸, 2칸, 1칸으로 1칸씩 줄여 맞닿게 그린다. 그다음은 다시 3칸이므로 넷째 원의 반지름은 3칸이다.","scoring_points":["원의 중심을 옮기는 규칙을 썼는가","반지름의 규칙을 썼는가","규칙에 맞게 넷째 원의 반지름을 구했는가"]},"explanation":["중심을 어느 쪽으로 몇 칸 옮길지 정해요.","반지름이 어떻게 바뀔지 정해요.","규칙대로 넷째 원의 반지름을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#1','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C1',1,'mc','auto','원은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"원은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉯만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"oval":[[45,45,39.0,31.5]]},{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"poly":[[[45.0,10.5],[10.5,45.0],[45.0,79.5],[79.5,45.0]]]}]},"variant_rule":{"alt":[{"stem":"어느 쪽으로 보아도 똑같이 둥근 모양은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉮만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"oval":[[45,45,39.0,24.0]]},{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"oval":[[45,45,22.5,37.5]]}]}},{"stem":"포이와 드림캐처에서 볼 수 있는 모양과 같은 모양은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉯","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉱만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"poly":[[[45.0,10.5],[10.5,45.0],[45.0,79.5],[79.5,45.0]]]},{"w":90,"h":90,"oval":[[45,45,22.5,37.5]]},{"w":90,"h":90,"circle":[[[45,45],34.5]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#2','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C2',1,'mc','auto','원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X01']::text[],true,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 반지름이에요."],"variant_rule":{"alt":[{"stem":"원의 가장 안쪽에 있는 한 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"asset":null},{"stem":"누름 못과 띠종이로 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#3','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',1,'mc','auto','이 원의 지름을 찾아보세요. 어느 선분인가요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"이 원의 지름을 찾아보세요. 어느 선분인가요?","options":[{"t":"선분 ㅁㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-2-u3-X06"},{"t":"선분 ㅂㄱ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㅁㄹ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㅁ":[30.1,34.9,"nw"],"ㄹ":[89.9,85.1,"se"],"ㄴ":[21.6,66.8,"w"],"ㄷ":[60.0,99.0,"s"],"ㅂ":[99.0,60.0,"e"],"ㄱ":[53.2,21.6,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㅁ","ㄹ"],["ㄴ","ㄷ"],["ㅂ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심을 지나는 선분은 어느 것인가요?","options":[{"t":"선분 ㄴㅂ","correct":true},{"t":"선분 ㄹㅁ","mis":"M3-2-u3-X06"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄴㅂ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄴ":[23.4,73.3,"w"],"ㅂ":[96.6,46.7,"e"],"ㄹ":[46.7,96.6,"s"],"ㅁ":[93.8,79.5,"se"],"ㄱ":[79.5,26.2,"ne"],"ㄷ":[23.4,46.7,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㄴ","ㅂ"],["ㄹ","ㅁ"],["ㄱ","ㄷ"]]}],"tag":false}},{"stem":"지름은 어느 선분인가요?","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄷㄹ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅂ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄱㄴ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[93.8,40.5,"ne"],"ㄴ":[26.2,79.5,"sw"],"ㄷ":[66.8,21.6,"n"],"ㄹ":[23.4,46.7,"w"],"ㅁ":[46.7,96.6,"s"],"ㅂ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#4','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',1,'sa','auto','선풍기 모양 원의 지름이 14 cm예요. 다른 쪽으로 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"선풍기 모양 원의 지름이 14 cm예요. 다른 쪽으로 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","14 cm예요."],"variant_rule":{"alt":[{"stem":"한 원에 그은 지름 하나가 16 cm예요. 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","16 cm예요."],"asset":null},{"stem":"지름이 18 cm인 원에 지름을 하나 더 그었어요. 새로 그은 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","18 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#5','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',1,'sa','auto','반지름이 8 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 원에서 지름은 반지름의 2배예요.","8 cm의 2배를 구해요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"드림캐처 모양 원의 반지름이 6 cm예요. 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["한 원에서 지름은 반지름의 2배예요.","6 cm의 2배를 구해요.","6 × 2 = 12 — 지름은 12 cm예요."],"asset":null},{"stem":"반지름이 9 cm인 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 원에서 지름은 반지름의 2배예요.","9 cm의 2배를 구해요.","9 × 2 = 18 — 지름은 18 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#6','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',1,'mc','auto','원 모양 종이를 똑같이 둘로 접었다 폈을 때 접힌 선은 원의 무엇인가요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"원 모양 종이를 똑같이 둘로 접었다 폈을 때 접힌 선은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"variant_rule":{"alt":[{"stem":"원을 똑같이 둘로 나누는 선분은 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 두 점을 이은 아무 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심","mis":"M3-2-u3-X03"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"asset":null},{"stem":"원 모양 종이를 똑같이 둘로 두 번 접었다 폈어요. 두 접힌 선이 만나는 점은 무엇인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"반지름","mis":"M3-2-u3-X07"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","지름 두 개가 만나는 점은 원의 중심이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#7','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',1,'mc','auto','컴퍼스로 원을 그릴 때 가장 먼저 할 일은 무엇인가요?',ARRAY['M3-2-u3-X12','M3-2-u3-X07']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스로 원을 그릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"원의 중심이 되는 점을 정해요","correct":true},{"t":"컴퍼스를 돌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"},{"t":"침을 원 위에 꽂아요","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그릴 때 침은 어디에 꽂나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X12"},{"t":"지름의 한 끝","mis":"M3-2-u3-X11"},{"t":"아무 곳이나","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null},{"stem":"컴퍼스로 원을 그리는 마지막 걸음은 무엇인가요?","options":[{"t":"침을 원의 중심에 꽂고 한 바퀴 돌려 그려요","correct":true},{"t":"원의 중심을 정해요","mis":"M3-2-u3-X12"},{"t":"컴퍼스를 반지름만큼 벌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#8','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C7',1,'mc','auto','모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"모두 1칸이에요","correct":true},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"2칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 1, 1, 1칸.","규칙: 반지름이 모두 1칸이에요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"2칸, 1칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 2, 1, 2, 1칸.","규칙: 반지름이 2칸, 1칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸, 2칸, 3칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 3, 1, 2칸.","규칙: 반지름이 1칸, 2칸, 3칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":300,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15],[[255,60],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#9','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C1',2,'mc','auto','원 위에 있는 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],true,'{"seq":9,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위에 있는 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄹ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄱ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄹ":[60.0,22.5,"n"],"ㄴ":[49.2,72.9,"sw"],"ㄱ":[109.9,51.2,"e"]},"circle":[[[60,60],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 굽은 선 위에 놓인 점은 어느 것인가요?","options":[{"t":"점 ㄱ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄱ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄷ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄱ":[35.9,31.3,"nw"],"ㄴ":[68.4,74.6,"se"],"ㄷ":[107.6,42.7,"e"]},"circle":[[[60,60],37.5]]}],"tag":false}},{"stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄴ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄷ":[24.8,72.8,"w"],"ㄱ":[68.4,45.4,"ne"],"ㄴ":[103.8,85.3,"se"]},"circle":[[[60,60],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.mis