INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#19','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C5',3,'mc','auto','큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 반지름 5 · ㉡ 지름 8 · ㉢ 반지름 3 · ㉣ 지름 12, 단위 cm)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],true,'{"seq":19,"concept":"M3-2-u3-C5","difficulty":3,"kind":"mc","stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 반지름 5 · ㉡ 지름 8 · ㉢ 반지름 3 · ㉣ 지름 12, 단위 cm)","options":[{"t":"㉣, ㉠, ㉡, ㉢","correct":true},{"t":"㉣, ㉡, ㉠, ㉢","mis":"M3-2-u3-X10"},{"t":"㉢, ㉡, ㉠, ㉣","mis":"M3-2-u3-X16"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M3-2-u3-X10"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 10, ㉡ 8, ㉢ 6, ㉣ 12(cm).","큰 것부터 ㉣, ㉠, ㉡, ㉢이에요."],"variant_rule":{"alt":[{"stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 지름 9 · ㉡ 반지름 4 · ㉢ 반지름 7 · ㉣ 지름 5, 단위 cm)","options":[{"t":"㉢, ㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢, ㉣, ㉡","mis":"M3-2-u3-X10"},{"t":"㉢, ㉡, ㉠, ㉣","mis":"M3-2-u3-X10"},{"t":"㉣, ㉡, ㉠, ㉢","mis":"M3-2-u3-X16"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 9, ㉡ 8, ㉢ 14, ㉣ 5(cm).","큰 것부터 ㉢, ㉠, ㉡, ㉣이에요."],"asset":null},{"stem":"큰 원부터 차례로 놓은 것은 어느 것인가요? (㉠ 지름 10 · ㉡ 반지름 3 · ㉢ 반지름 6 · ㉣ 지름 7, 단위 cm)","options":[{"t":"㉢, ㉠, ㉣, ㉡","correct":true},{"t":"㉠, ㉣, ㉢, ㉡","mis":"M3-2-u3-X10"},{"t":"㉢, ㉣, ㉠, ㉡","mis":"M3-2-u3-X10"},{"t":"㉡, ㉣, ㉠, ㉢","mis":"M3-2-u3-X16"}],"explanation":["모두 지름으로 바꾸어요.","㉠ 10, ㉡ 6, ㉢ 12, ㉣ 7(cm).","큰 것부터 ㉢, ㉠, ㉣, ㉡이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#20','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C8',3,'mc','auto','반지름이 5 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?',ARRAY['M3-2-u3-X15','M3-2-u3-X08']::text[],true,'{"seq":20,"concept":"M3-2-u3-C8","difficulty":3,"kind":"mc","stem":"반지름이 5 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"20 cm","correct":true},{"t":"30 cm","mis":"M3-2-u3-X15"},{"t":"10 cm","mis":"M3-2-u3-X08"},{"t":"15 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 4개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 4개 = 지름 2개예요.","10 × 2 = 20(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[84.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원 4개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"32 cm","mis":"M3-2-u3-X15"},{"t":"12 cm","mis":"M3-2-u3-X08"},{"t":"16 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 6개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 6개 = 지름 3개예요.","8 × 3 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[114.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심 ㄱ에서 마지막 원의 중심 ㄴ까지는 몇 cm인가요?","options":[{"t":"8 cm","correct":true},{"t":"12 cm","mis":"M3-2-u3-X15"},{"t":"4 cm","mis":"M3-2-u3-X08"},{"t":"6 cm","mis":"M3-2-u3-X15"}],"explanation":["선분 ㄱㄴ 위에는 반지름이 4개 들어 있어요(양 끝 원은 반지름 하나씩, 가운데 원은 지름).","반지름 4개 = 지름 2개예요.","4 × 2 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[84.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#21','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C6',3,'mc','auto','이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?',ARRAY['M3-2-u3-X15']::text[],true,'{"seq":21,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 4개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 3군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[37.5,45],22.5],[[82.5,45],22.5],[[127.5,45],22.5],[[82.5,45],12.0]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"1군데","correct":true},{"t":"3군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"4군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 3개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 1군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[75,45],37.5],[[75,45],22.5],[[75,45],9.0]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 모양을 컴퍼스로 똑같이 그리려고 해요. 침을 꽂아야 하는 곳은 모두 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M3-2-u3-X15"},{"t":"2군데","mis":"M3-2-u3-X15"},{"t":"6군데","mis":"M3-2-u3-X15"}],"explanation":["침은 원의 중심에 꽂아요.","원은 3개지만 중심이 같은 원은 한 곳에 꽂고 벌린 길이만 바꾸면 돼요.","중심은 3군데예요."],"asset":{"type":"geo","items":[{"w":157.5,"h":90,"circle":[[[45,45],18.0],[[81.0,45],18.0],[[117.0,45],18.0]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#22','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C7',3,'sa','auto','이 규칙대로 원 3개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"이 규칙대로 원 3개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["반지름: 1, 2, 3칸.","가로에는 원마다 지름이 하나씩 놓여요 — 2, 4, 6칸.","2 + 4 + 6 = 12칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원 5개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["반지름: 2, 1, 2, 1, 2칸.","가로에는 원마다 지름이 하나씩 놓여요 — 4, 2, 4, 2, 4칸.","4 + 2 + 4 + 2 + 4 = 16칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false}},{"stem":"이 규칙대로 원 4개를 맞닿게 한 줄로 그렸어요. 무늬의 왼쪽 끝에서 오른쪽 끝까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["반지름: 1, 2, 3, 4칸.","가로에는 원마다 지름이 하나씩 놓여요 — 2, 4, 6, 8칸.","2 + 4 + 6 + 8 = 20칸이에요."],"asset":{"type":"geo","items":[{"w":330,"h":150,"grid":15,"circle":[[[30,75],15],[[75,75],30],[[150,75],45],[[255,75],60]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#23','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C8',4,'sa','auto','큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 16 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 16 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 16의 반 = 8(cm).","작은 원의 반지름: 8의 반 = 4(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 20 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 20의 반 = 10(cm).","작은 원의 반지름: 10의 반 = 5(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"큰 원 안에 크기가 같은 작은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 큰 원의 지름 ㄱㄴ이 24 cm일 때, 작은 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 원의 지름 ㄱㄴ 위에 작은 원의 지름이 2개 있어요.","작은 원의 지름: 24의 반 = 12(cm).","작은 원의 반지름: 12의 반 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"circle":[[[67.5,45],39.0],[[48.0,45],19.5],[[87.0,45],19.5]],"pts":{"ㄱ":[28.5,45,"w"],"ㄴ":[106.5,45,"e"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#24','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C3',4,'mc','auto','원 위에 점 6개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?',ARRAY['M3-2-u3-X15','M3-2-u3-X06','M3-2-u3-X04']::text[],true,'{"seq":24,"concept":"M3-2-u3-C3","difficulty":4,"kind":"mc","stem":"원 위에 점 6개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M3-2-u3-X15"},{"t":"15개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","6개를 둘씩 짝 지으면 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[60.0,21.0,"n"],"ㄴ":[93.8,40.5,"ne"],"ㄷ":[93.8,79.5,"se"],"ㄹ":[60.0,99.0,"s"],"ㅁ":[26.2,79.5,"sw"],"ㅂ":[26.2,40.5,"nw"]},"circle":[[[60,60],39.0]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원 위에 점 10개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"10개","mis":"M3-2-u3-X15"},{"t":"45개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","10개를 둘씩 짝 지으면 5개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[60.0,21.0,"n"],"ㄴ":[82.9,28.4,"ne"],"ㄷ":[97.1,47.9,"e"],"ㄹ":[97.1,72.1,"e"],"ㅁ":[82.9,91.6,"se"],"ㅂ":[60.0,99.0,"s"],"ㅅ":[37.1,91.6,"sw"],"ㅈ":[22.9,72.1,"w"],"ㅊ":[22.9,47.9,"w"],"ㅋ":[37.1,28.4,"nw"]},"circle":[[[60,60],39.0]]}],"tag":false}},{"stem":"원 위에 점 12개가 같은 간격으로 놓여 있어요. 두 점을 이어 그을 수 있는 지름은 모두 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"12개","mis":"M3-2-u3-X15"},{"t":"66개","mis":"M3-2-u3-X06"},{"t":"2개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나야 해요.","한 점과 마주 보는 점을 이어야 중심을 지나요 — 두 점이 한 짝이에요.","12개를 둘씩 짝 지으면 6개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[60.0,21.0,"n"],"ㄴ":[79.5,26.2,"ne"],"ㄷ":[93.8,40.5,"ne"],"ㄹ":[99.0,60.0,"e"],"ㅁ":[93.8,79.5,"se"],"ㅂ":[79.5,93.8,"se"],"ㅅ":[60.0,99.0,"s"],"ㅈ":[40.5,93.8,"sw"],"ㅊ":[26.2,79.5,"sw"],"ㅋ":[21.0,60.0,"w"],"ㅌ":[26.2,40.5,"nw"],"ㅍ":[40.5,26.2,"nw"]},"circle":[[[60,60],39.0]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_a#25','math',3,2,'u3','','g3_2_math_u3_review_a','unit_review','M3-2-u3-C4',4,'essay','teacher','나래는 「반지름은 지름의 2배야.」라고 말했어요. 나래의 말이 잘못된 까닭을 쓰고, 반지름이 6 cm인 원의 지름을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C4","difficulty":4,"kind":"essay","stem":"나래는 「반지름은 지름의 2배야.」라고 말했어요. 나래의 말이 잘못된 까닭을 쓰고, 반지름이 6 cm인 원의 지름을 구해 보세요.","answer_guide":{"answer":"예: 지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이라 반지름 2개를 이은 것과 같다. 그래서 지름이 반지름의 2배이고, 반지름은 지름의 반이다. 반지름 6 cm인 원의 지름은 6 × 2 = 12(cm)이다.","scoring_points":["지름이 반지름의 2배(반지름은 지름의 반)라고 바로잡았는가","지름이 반지름 2개로 이루어진다는 까닭을 썼는가","지름 12 cm를 구했는가"]},"explanation":["지름 = 반지름 2개.","그래서 지름이 반지름의 2배예요.","6 × 2 = 12(cm)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#1','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C1',1,'mc','auto','원을 바르게 설명한 것은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"원을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"굽은 선으로 되어 있어요","correct":true},{"t":"곧은 선 3개로 둘러싸여 있어요","mis":"M3-2-u3-X01"},{"t":"꼭짓점이 3개 있어요","mis":"M3-2-u3-X01"},{"t":"한쪽으로 길쭉해요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「굽은 선으로 되어 있어요」예요."],"variant_rule":{"alt":[{"stem":"동전을 본떠 그린 원에 대해 알맞은 말은 어느 것인가요?","options":[{"t":"어느 쪽으로 보아도 똑같이 둥글어요","correct":true},{"t":"한쪽으로 길쭉해도 돼요","mis":"M3-2-u3-X01"},{"t":"뾰족한 곳이 하나 있어요","mis":"M3-2-u3-X01"},{"t":"곧은 선이 4개 있어요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「어느 쪽으로 보아도 똑같이 둥글어요」예요."],"asset":null},{"stem":"원의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"꼭짓점이 없어요","correct":true},{"t":"꼭짓점이 4개 있어요","mis":"M3-2-u3-X01"},{"t":"곧은 선으로 둘러싸여 있어요","mis":"M3-2-u3-X01"},{"t":"뾰족한 곳이 있어요","mis":"M3-2-u3-X01"}],"explanation":["원은 굽은 선으로 된 모양이에요.","꼭짓점·뾰족한 곳·곧은 선이 없고, 어느 쪽으로 보아도 똑같이 둥글어요.","알맞은 말은 「꼭짓점이 없어요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#2','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',1,'mc','auto','한 원에서 반지름의 길이는 어떤가요?',ARRAY['M3-2-u3-X05']::text[],true,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"한 원에서 반지름의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"그은 자리마다 달라요","mis":"M3-2-u3-X05"},{"t":"위쪽으로 그은 것이 가장 길어요","mis":"M3-2-u3-X05"},{"t":"알 수 없어요","mis":"M3-2-u3-X05"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원의 중심에서 원 위의 어느 점까지나 길이가 같아요.","그래서 「모두 같아요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"한 원에 반지름은 몇 개 그을 수 있나요?","options":[{"t":"셀 수 없이 많아요","correct":true},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"},{"t":"4개","mis":"M3-2-u3-X04"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원 위의 점마다 반지름을 하나씩 그을 수 있어요 — 원 위의 점은 셀 수 없이 많아요.","그래서 「셀 수 없이 많아요」가 알맞아요."],"asset":null},{"stem":"한 원에 원의 중심은 몇 개 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M3-2-u3-X03"},{"t":"4개","mis":"M3-2-u3-X03"},{"t":"셀 수 없이 많아요","mis":"M3-2-u3-X03"}],"explanation":["원은 한 점(중심)에서 같은 길이만큼 떨어진 점들로 이루어져요.","원의 중심은 원의 가장 안쪽 한 점이에요 — 한 원에 하나뿐이에요.","그래서 「1개」가 알맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#3','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',1,'mc','auto','원 위의 두 점을 이은 선분이 원의 중심을 지날 때, 그 선분을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X03','M3-2-u3-X02']::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"원 위의 두 점을 이은 선분이 원의 중심을 지날 때, 그 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「지름」이에요."],"variant_rule":{"alt":[{"stem":"지름은 원 위의 두 점을 이은 선분 가운데 어떤 선분인가요?","options":[{"t":"원의 중심을 지나는 선분","correct":true},{"t":"가장 짧은 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이은 선분","mis":"M3-2-u3-X07"},{"t":"원 밖의 점을 지나는 선분","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「원의 중심을 지나는 선분」이에요."],"asset":null},{"stem":"시계에서 12와 6을 잇는 선분은 시곗바늘이 도는 가운데를 지나요. 이 선분은 시계 모양 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원 위의 두 점을 이은 선분 가운데","원의 중심을 지나는 선분을 지름이라고 해요.","그래서 답은 「지름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#4','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',1,'mc','auto','한 원에서 지름은 모두 어느 점을 지나나요?',ARRAY['M3-2-u3-X06','M3-2-u3-X02']::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"한 원에서 지름은 모두 어느 점을 지나나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X06"},{"t":"원 밖의 한 점","mis":"M3-2-u3-X02"},{"t":"지나는 점이 모두 달라요","mis":"M3-2-u3-X06"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「원의 중심」이에요."],"variant_rule":{"alt":[{"stem":"한 원에 지름은 몇 개 그을 수 있나요?","options":[{"t":"셀 수 없이 많아요","correct":true},{"t":"1개","mis":"M3-2-u3-X04"},{"t":"2개","mis":"M3-2-u3-X04"},{"t":"4개","mis":"M3-2-u3-X04"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「셀 수 없이 많아요」예요."],"asset":null},{"stem":"한 원에서 지름의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"그은 방향마다 달라요","mis":"M3-2-u3-X05"},{"t":"가로로 그은 것이 가장 길어요","mis":"M3-2-u3-X05"},{"t":"알 수 없어요","mis":"M3-2-u3-X05"}],"explanation":["지름은 원의 중심을 지나 원 위의 두 점을 이은 선분이에요.","원 위의 점마다 그을 수 있어 셀 수 없이 많고, 모두 중심을 지나며 길이가 같아요.","답은 「모두 같아요」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#5','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',1,'sa','auto','접시 모양 원의 지름이 16 cm예요. 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"접시 모양 원의 지름이 16 cm예요. 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 반지름은 지름의 반이에요.","16 cm를 똑같이 둘로 나눠요.","16의 반은 8 — 반지름은 8 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 18 cm인 원에 반지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 원에서 반지름은 지름의 반이에요.","18 cm를 똑같이 둘로 나눠요.","18의 반은 9 — 반지름은 9 cm예요."],"asset":null},{"stem":"지름이 6 cm인 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 원에서 반지름은 지름의 반이에요.","6 cm를 똑같이 둘로 나눠요.","6의 반은 3 — 반지름은 3 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#6','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',1,'mc','auto','점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?',ARRAY['M3-2-u3-X17']::text[],true,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄴ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[96.6,46.7,"e"],"ㄴ":[23.4,73.3,"w"],"ㄷ":[30.1,34.9,"nw"],"ㄹ":[53.2,98.4,"s"],"ㅁ":[21.6,53.2,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄹ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄷ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[23.4,73.3,"w"],"ㄷ":[96.6,46.7,"e"],"ㄹ":[85.1,30.1,"ne"],"ㅁ":[95.3,76.5,"se"],"ㄴ":[79.5,93.8,"se"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㄱ에서 그은 선분 가운데 가장 긴 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㅁ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X17"},{"t":"선분 ㄱㄷ","mis":"M3-2-u3-X17"}],"explanation":["점 ㄱ에서 원 위의 여러 점까지 선분을 그었어요.","원의 중심 ㅇ을 지나는 선분 ㄱㄹ이 지름이에요.","지름은 원 안에 그을 수 있는 가장 긴 선분이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[46.7,96.6,"s"],"ㄹ":[73.3,23.4,"n"