INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#7','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',1,'mc','auto','컴퍼스를 벌린 길이를 2배 하면 그려지는 원의 무엇과 같나요?',ARRAY['M3-2-u3-X08','M3-2-u3-X12']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스를 벌린 길이를 2배 하면 그려지는 원의 무엇과 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X08"},{"t":"원의 중심","mis":"M3-2-u3-X12"},{"t":"컴퍼스의 길이","mis":"M3-2-u3-X12"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「지름」이에요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침이 꽂힌 점은 그려지는 원의 무엇인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「원의 중심」이에요."],"asset":null},{"stem":"컴퍼스의 침과 연필 끝 사이를 벌린 길이는 원의 무엇과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X11"},{"t":"원의 중심","mis":"M3-2-u3-X12"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["컴퍼스의 침이 꽂힌 점이 원의 중심이에요.","침과 연필 끝 사이 길이가 반지름 — 그 2배가 지름이에요.","답은 「반지름」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#8','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',1,'mc','auto','반지름이 모눈 4칸인 원의 지름은 모눈 몇 칸인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"반지름이 모눈 4칸인 원의 지름은 모눈 몇 칸인가요?","options":[{"t":"8칸","correct":true},{"t":"4칸","mis":"M3-2-u3-X09"},{"t":"5칸","mis":"M3-2-u3-X09"},{"t":"16칸","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름의 2배예요.","4 × 2 = 8.","지름은 8칸이에요."],"variant_rule":{"alt":[{"stem":"모눈 위에 반지름이 2칸인 원을 그렸어요. 지름은 몇 칸인가요?","options":[{"t":"4칸","correct":true},{"t":"2칸","mis":"M3-2-u3-X09"},{"t":"3칸","mis":"M3-2-u3-X09"},{"t":"8칸","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름의 2배예요.","2 × 2 = 4.","지름은 4칸이에요."],"asset":null},{"stem":"반지름 3칸인 원을 그리면 원의 왼쪽 끝에서 오른쪽 끝까지 몇 칸인가요?","options":[{"t":"6칸","correct":true},{"t":"3칸","mis":"M3-2-u3-X09"},{"t":"4칸","mis":"M3-2-u3-X09"},{"t":"12칸","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름의 2배예요.","3 × 2 = 6.","지름은 6칸이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#9','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C1',2,'mc','auto','본떠서 원을 그릴 수 있는 물건은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":9,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"컵의 바닥","correct":true},{"t":"필통 옆면","mis":"M3-2-u3-X01"},{"t":"삼각자","mis":"M3-2-u3-X01"},{"t":"책","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","컵의 바닥을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"병뚜껑","correct":true},{"t":"색종이","mis":"M3-2-u3-X01"},{"t":"달걀","mis":"M3-2-u3-X01"},{"t":"공책","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","병뚜껑을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 본떠서 원을 그릴 수 있는 물건은 어느 것인가요?","options":[{"t":"동전","correct":true},{"t":"공책","mis":"M3-2-u3-X01"},{"t":"삼각자","mis":"M3-2-u3-X01"},{"t":"지우개","mis":"M3-2-u3-X01"}],"explanation":["본뜬 모양이 똑같이 둥근 물건을 골라요.","동전을 대고 따라 그리면 원이 돼요.","꼭짓점이 있거나 길쭉한 물건은 원이 되지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#10','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',2,'sa','auto','띠종이에 누름 못에서 1, 2, 3, 4 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 2 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":2,"kind":"sa","stem":"띠종이에 누름 못에서 1, 2, 3, 4 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 2 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 2 cm예요."],"variant_rule":{"alt":[{"stem":"띠종이에 누름 못에서 2, 3, 4, 5 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 4 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 4 cm예요."],"asset":null},{"stem":"띠종이에 누름 못에서 1, 3, 5, 6 cm 떨어진 곳마다 구멍이 있어요. 누름 못에서 6 cm 떨어진 구멍에 연필을 넣고 한 바퀴 돌렸어요. 그려진 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["누름 못이 꽂힌 점이 원의 중심이에요.","연필이 지나간 자리가 원이고, 누름 못에서 연필까지가 반지름이에요.","반지름은 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
