INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#12','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',2,'mc','auto','카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":12,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 3 cm · 지름 6 cm","correct":true},{"t":"반지름 4 cm · 지름 4 cm","mis":"M3-2-u3-X09"},{"t":"반지름 6 cm · 지름 3 cm","mis":"M3-2-u3-X08"},{"t":"반지름 2 cm · 지름 8 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 3 cm인 원의 지름은 6 cm예요.","반지름 3 cm · 지름 6 cm가 같은 원이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 4 cm · 지름 8 cm","correct":true},{"t":"반지름 5 cm · 지름 5 cm","mis":"M3-2-u3-X09"},{"t":"반지름 8 cm · 지름 4 cm","mis":"M3-2-u3-X08"},{"t":"반지름 3 cm · 지름 12 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 4 cm인 원의 지름은 8 cm예요.","반지름 4 cm · 지름 8 cm가 같은 원이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 5 cm · 지름 10 cm","correct":true},{"t":"반지름 6 cm · 지름 6 cm","mis":"M3-2-u3-X09"},{"t":"반지름 10 cm · 지름 5 cm","mis":"M3-2-u3-X08"},{"t":"반지름 4 cm · 지름 16 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 5 cm인 원의 지름은 10 cm예요.","반지름 5 cm · 지름 10 cm가 같은 원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#13','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',2,'mc','auto','가장 작은 원은 어느 것인가요? (㉠ 반지름 7 cm, ㉡ 지름 13 cm, ㉢ 반지름 6 cm)',ARRAY['M3-2-u3-X16','M3-2-u3-X10']::text[],true,'{"seq":13,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 7 cm, ㉡ 지름 13 cm, ㉢ 반지름 6 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X16"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 14 cm, ㉡ 지름 13 cm, ㉢ 지름 12 cm.","가장 작은 원은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 5 cm, ㉡ 반지름 6 cm, ㉢ 지름 11 cm)","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"㉢","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 10 cm, ㉡ 지름 12 cm, ㉢ 지름 11 cm.","가장 작은 원은 ㉠이에요."],"asset":null},{"stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 8 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm.","가장 작은 원은 ㉢이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#14','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',2,'sa','auto','컴퍼스의 침과 연필 끝 사이를 2 cm로 하고 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"컴퍼스의 침과 연필 끝 사이를 2 cm로 하고 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["벌린 길이 2 cm가 반지름이에요.","지름은 반지름의 2배예요.","2 × 2 = 4(cm)예요."],"variant_rule":{"alt":[{"stem":"6 cm 벌린 컴퍼스로 그린 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["벌린 길이 6 cm가 반지름이에요.","지름은 반지름의 2배예요.","6 × 2 = 12(cm)예요."],"asset":null},{"stem":"컴퍼스를 1 cm 벌려 그린 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["벌린 길이 1 cm가 반지름이에요.","지름은 반지름의 2배예요.","1 × 2 = 2(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#15','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',2,'sa','auto','원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["3"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","3칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]],"pts":{"①":[30,45,"n"],"②":[75,45,"n"],"③":[120,45,"n"],"④":[165,45,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["2"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","2칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15]],"pts":{"①":[30,30,"n"],"②":[60,30,"n"],"③":[90,30,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["2"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","2칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]],"pts":{"①":[30,30,"n"],"②":[60,30,"n"],"③":[90,30,"n"],"④":[120,30,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#16','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C4',2,'sa','auto','선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분 ㄱㄴ은 지름 — 6 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","6의 반 — 3 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.2,21.6,"n"],"ㄴ":[66.8,98.4,"s"],"ㄷ":[26.2,79.5,"sw"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[62.5,31.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["선분 ㄱㄴ은 지름 — 8 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","8의 반 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[99.0,60.0,"e"],"ㄴ":[21.0,60.0,"w"],"ㄷ":[46.7,23.4,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[88.1,67.5],"8 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 선분 ㄱㄴ은 원의 중심 ㅇ을 지나요. 선분 ㅇㄷ은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["선분 ㄱㄴ은 지름 — 10 cm예요.","선분 ㅇㄷ은 반지름이고, 반지름은 지름의 반이에요.","10의 반 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[79.5,26.2,"ne"],"ㄴ":[40.5,93.8,"sw"],"ㄷ":[21.6,53.2,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㅇ","ㄷ"]],"lab":[[[80.5,39.4],"10 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#17','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C2',3,'ox','auto','한 원에 원의 중심은 여러 개 있어요.',ARRAY['M3-2-u3-X03']::text[],true,'{"seq":17,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"한 원에 원의 중심은 여러 개 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"mis":"M3-2-u3-X03","explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"누름 못이 꽂힌 점은 원 위의 점이에요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"원의 중심은 원 위에 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
