INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#19','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C5',3,'ox','auto','반지름 8 cm인 원과 지름 8 cm인 원 가운데 어느 원도 더 크지 않아요.',ARRAY['M3-2-u3-X10']::text[],true,'{"seq":19,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"반지름 8 cm인 원과 지름 8 cm인 원 가운데 어느 원도 더 크지 않아요.","answer":"X","reason_options":[{"t":"반지름 8 cm인 원은 지름이 16 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["반지름 8 cm인 원의 지름은 16 cm예요.","지름 8 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원과 지름이 4 cm인 원은 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 4 cm인 원은 지름이 8 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 4 cm인 원의 지름은 8 cm예요.","지름 4 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null},{"stem":"지름이 6 cm인 원은 반지름이 6 cm인 원과 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 6 cm인 원은 지름이 12 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 6 cm인 원의 지름은 12 cm예요.","지름 6 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#20','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C8',3,'sa','auto','반지름이 5 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-2-u3-C8","difficulty":3,"kind":"sa","stem":"반지름이 5 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직사각형의 가로에는 원의 지름이 4개, 세로에는 1개 들어 있어요.","지름은 5 × 2 = 10(cm).","10 × 4 = 40(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"seg":[[[9.0,9.0],[129.0,9.0]],[[129.0,9.0],[129.0,39.0]],[[129.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원 3개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직사각형의 가로에는 원의 지름이 3개, 세로에는 1개 들어 있어요.","지름은 2 × 2 = 4(cm).","세로는 지름 하나 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"seg":[[[9.0,9.0],[99.0,9.0]],[[99.0,9.0],[99.0,39.0]],[[99.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false}},{"stem":"반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직사각형의 가로에는 원의 지름이 4개, 세로에는 1개 들어 있어요.","지름은 3 × 2 = 6(cm).","6 × 4 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"seg":[[[9.0,9.0],[129.0,9.0]],[[129.0,9.0],[129.0,39.0]],[[129.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#21','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',3,'mc','auto','지름이 8 cm인 원을 그리려고 컴퍼스를 8 cm 벌려 그렸어요. 어떤 원이 그려지나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08','M3-2-u3-X12']::text[],true,'{"seq":21,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"지름이 8 cm인 원을 그리려고 컴퍼스를 8 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 16 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 8 cm는 반지름이 돼요.","지름은 반지름의 2배 — 16 cm예요.","지름 8 cm인 원을 그리려면 4 cm만 벌려야 해요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원을 그리려고 컴퍼스를 10 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 20 cm인 원","correct":true},{"t":"지름이 10 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 5 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 10 cm는 반지름이 돼요.","지름은 반지름의 2배 — 20 cm예요.","지름 10 cm인 원을 그리려면 5 cm만 벌려야 해요."],"asset":null},{"stem":"지름이 4 cm인 원을 그리려고 컴퍼스를 4 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 4 cm는 반지름이 돼요.","지름은 반지름의 2배 — 8 cm예요.","지름 4 cm인 원을 그리려면 2 cm만 벌려야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#22','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 무늬예요. 둘째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 무늬예요. 둘째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["둘째 원은 반지름, 사이의 원은 지름, 넷째 원은 반지름만큼 들어 있어요.","2 + 2 + 2칸.","모두 6칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["첫째 원은 반지름, 사이의 원은 지름, 넷째 원은 반지름만큼 들어 있어요.","1 + 4 + 2 + 2칸.","모두 9칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}},{"stem":"원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 셋째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["첫째 원은 반지름, 사이의 원은 지름, 셋째 원은 반지름만큼 들어 있어요.","1 + 4 + 3칸.","모두 8칸이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#23','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C8',4,'sa','auto','직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 24 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 24 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["가로에는 원의 지름이 2개 들어 있어요.","지름: 24의 반 = 12(cm).","반지름: 12의 반 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 8 cm일 때 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가로에는 원의 지름이 2개, 세로에는 1개 들어 있어요.","지름 하나: 8의 반 = 4(cm).","세로는 지름 하나 — 4 cm예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}},{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 12 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가로에는 원의 지름이 2개 들어 있어요.","지름: 12의 반 = 6(cm).","반지름: 6의 반 = 3(cm)예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#24','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C3',4,'sa','auto','원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 7 cm이고 삼각형의 세 변의 길이의 합은 19 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 7 cm이고 삼각형의 세 변의 길이의 합은 19 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 19 − 7 = 12(cm).","반지름 하나는 12의 반 — 6 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[31.3,84.1,"sw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 9 cm이고 삼각형의 세 변의 길이의 합은 23 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 23 − 9 = 14(cm).","반지름 하나는 14의 반 — 7 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[78.8,92.5,"se"],"ㄴ":[78.8,27.5,"ne"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 4 cm이고 삼각형의 세 변의 길이의 합은 10 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 10 − 4 = 6(cm).","반지름 하나는 6의 반 — 3 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[95.2,47.2,"e"],"ㄴ":[31.3,35.9,"nw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_b#25','math',3,2,'u3','','g3_2_math_u3_review_b','unit_review','M3-2-u3-C6',4,'essay','teacher','시우는 지름이 2 cm인 원을 그리려고 컴퍼스를 2 cm 벌렸어요. 시우가 그린 원은 어떤 원이 되는지 쓰고, 바르게 그리는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C6","difficulty":4,"kind":"essay","stem":"시우는 지름이 2 cm인 원을 그리려고 컴퍼스를 2 cm 벌렸어요. 시우가 그린 원은 어떤 원이 되는지 쓰고, 바르게 그리는 방법을 써 보세요.","answer_guide":{"answer":"예: 컴퍼스를 벌린 길이는 반지름이므로 반지름 2 cm, 지름 4 cm인 원이 그려진다. 지름이 2 cm인 원을 그리려면 지름의 반인 1 cm만 벌리고, 침을 원의 중심에 꽂아 돌려 그려야 한다.","scoring_points":["지름 4 cm(반지름 2 cm)인 원이 된다고 썼는가","컴퍼스를 벌린 길이가 반지름이라고 썼는가","1 cm 벌려야 한다고 바로잡았는가"]},"explanation":["벌린 길이 = 반지름.","2 cm 벌리면 지름 4 cm.","지름 2 cm인 원은 1 cm 벌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#1','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C1',1,'mc','auto','포이와 드림캐처에서 볼 수 있는 모양과 같은 모양은 어느 것인가요?',ARRAY['M3-2-u3-X01']::text[],true,'{"seq":1,"concept":"M3-2-u3-C1","difficulty":1,"kind":"mc","stem":"포이와 드림캐처에서 볼 수 있는 모양과 같은 모양은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉯","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉱만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"poly":[[[45.0,10.5],[10.5,45.0],[45.0,79.5],[79.5,45.0]]]},{"w":90,"h":90,"oval":[[45,45,22.5,37.5]]},{"w":90,"h":90,"circle":[[[45,45],34.5]]}]},"variant_rule":{"alt":[{"stem":"원은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉯","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉰만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"oval":[[45,45,39.0,31.5]]},{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"oval":[[45,45,39.0,24.0]]}]}},{"stem":"어느 쪽으로 보아도 똑같이 둥근 모양은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M3-2-u3-X01"},{"t":"㉰","mis":"M3-2-u3-X01"},{"t":"㉱","mis":"M3-2-u3-X01"}],"explanation":["원은 꼭짓점이 없고 어느 쪽으로 보아도 똑같이 둥글어요.","㉯만 그래요 — 나머지는 한쪽으로 길쭉하거나 꼭짓점이 있어요.","굽은 선으로 둘러싸여도 길쭉하면 원이 아니에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"oval":[[45,45,39.0,31.5]]},{"w":90,"h":90,"circle":[[[45,45],34.5]]},{"w":90,"h":90,"poly":[[[45.0,9.0],[13.8,27.0],[13.8,63.0],[45.0,81.0],[76.2,63.0],[76.2,27.0]]]},{"w":90,"h":90,"poly":[[[45.0,10.5],[10.5,45.0],[45.0,79.5],[79.5,45.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#2','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C2',1,'mc','auto','누름 못과 띠종이로 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?',ARRAY['M3-2-u3-X07','M3-2-u3-X02']::text[],true,'{"seq":2,"concept":"M3-2-u3-C2","difficulty":1,"kind":"mc","stem":"누름 못과 띠종이로 원을 그릴 때 누름 못이 꽂힌 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"지름","mis":"M3-2-u3-X07"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 반지름이에요."],"asset":null},{"stem":"원의 가장 안쪽에 있는 한 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X02"},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"꼭짓점","mis":"M3-2-u3-X01"}],"explanation":["원의 중심: 누름 못이 꽂힌 점, 원의 가장 안쪽 한 점.","반지름: 원의 중심과 원 위의 한 점을 이은 선분.","그래서 답은 원의 중심이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#3','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',1,'mc','auto','지름은 어느 선분인가요?',ARRAY['M3-2-u3-X06']::text[],true,'{"seq":3,"concept":"M3-2-u3-C3","difficulty":1,"kind":"mc","stem":"지름은 어느 선분인가요?","options":[{"t":"선분 ㄱㄴ","correct":true},{"t":"선분 ㄷㄹ","mis":"M3-2-u3-X06"},{"t":"선분 ㅁㅂ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄱㄴ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[93.8,40.5,"ne"],"ㄴ":[26.2,79.5,"sw"],"ㄷ":[66.8,21.6,"n"],"ㄹ":[23.4,46.7,"w"],"ㅁ":[46.7,96.6,"s"],"ㅂ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 원의 지름을 찾아보세요. 어느 선분인가요?","options":[{"t":"선분 ㄷㅅ","correct":true},{"t":"선분 ㄱㄴ","mis":"M3-2-u3-X06"},{"t":"선분 ㄹㅁ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㄷㅅ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄷ":[60.0,21.0,"n"],"ㅅ":[60.0,99.0,"s"],"ㄱ":[30.1,34.9,"nw"],"ㄴ":[30.1,85.1,"sw"],"ㄹ":[85.1,89.9,"se"],"ㅁ":[85.1,30.1,"ne"]},"circle":[[[60,60],39.0]],"seg":[["ㄷ","ㅅ"],["ㄱ","ㄴ"],["ㄹ","ㅁ"]]}],"tag":false}},{"stem":"원의 중심을 지나는 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-2-u3-X06"},{"t":"선분 ㅂㄱ","mis":"M3-2-u3-X06"},{"t":"세 선분 모두","mis":"M3-2-u3-X06"}],"explanation":["세 선분 모두 원 위의 두 점을 이었어요.","원의 중심 ㅇ을 지나는 것은 선분 ㅁㄹ뿐이에요.","중심을 지나는 선분이 지름이에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㅁ":[30.1,34.9,"nw"],"ㄹ":[89.9,85.1,"se"],"ㄴ":[21.6,66.8,"w"],"ㄷ":[60.0,99.0,"s"],"ㅂ":[99.0,60.0,"e"],"ㄱ":[53.2,21.6,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㅁ","ㄹ"],["ㄴ","ㄷ"],["ㅂ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#4','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',1,'sa','auto','지름이 18 cm인 원에 지름을 하나 더 그었어요. 새로 그은 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u3-C3","difficulty":1,"kind":"sa","stem":"지름이 18 cm인 원에 지름을 하나 더 그었어요. 새로 그은 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","18 cm예요."],"variant_rule":{"alt":[{"stem":"선풍기 모양 원의 지름이 6 cm예요. 다른 쪽으로 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","6 cm예요."],"asset":null},{"stem":"한 원에 그은 지름 하나가 8 cm예요. 다른 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 지름은 셀 수 없이 많이 그을 수 있어요.","그 지름들의 길이는 모두 같아요.","8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#5','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',1,'sa','auto','반지름이 9 cm인 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u3-C4","difficulty":1,"kind":"sa","stem":"반지름이 9 cm인 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 원에서 지름은 반지름의 2배예요.","9 cm의 2배를 구해요.","9 × 2 = 18 — 지름은 18 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 원에서 지름은 반지름의 2배예요.","3 cm의 2배를 구해요.","3 × 2 = 6 — 지름은 6 cm예요."],"asset":null},{"stem":"드림캐처 모양 원의 반지름이 4 cm예요. 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 원에서 지름은 반지름의 2배예요.","4 cm의 2배를 구해요.","4 × 2 = 8 — 지름은 8 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#6','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',1,'mc','auto','원 모양 종이를 똑같이 둘로 두 번 접었다 폈어요. 두 접힌 선이 만나는 점은 무엇인가요?',ARRAY['M3-2-u3-X03','M3-2-u3-X07']::text[],true,'{"seq":6,"concept":"M3-2-u3-C5","difficulty":1,"kind":"mc","stem":"원 모양 종이를 똑같이 둘로 두 번 접었다 폈어요. 두 접힌 선이 만나는 점은 무엇인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 점","mis":"M3-2-u3-X03"},{"t":"지름","mis":"M3-2-u3-X07"},{"t":"반지름","mis":"M3-2-u3-X07"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","지름 두 개가 만나는 점은 원의 중심이에요."],"variant_rule":{"alt":[{"stem":"원 모양 종이를 똑같이 둘로 접었다 폈을 때 접힌 선은 원의 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원의 중심","mis":"M3-2-u3-X03"},{"t":"원 위의 점","mis":"M3-2-u3-X02"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"asset":null},{"stem":"원을 똑같이 둘로 나누는 선분은 무엇인가요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M3-2-u3-X07"},{"t":"원 위의 두 점을 이은 아무 선분","mis":"M3-2-u3-X06"},{"t":"원의 중심","mis":"M3-2-u3-X03"}],"explanation":["원을 똑같이 둘로 접으면 접힌 선이 원의 중심을 지나요.","그 선분이 지름이고, 지름은 원을 똑같이 둘로 나눠요.","그래서 답은 지름이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#7','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',1,'mc','auto','컴퍼스로 원을 그리는 마지막 걸음은 무엇인가요?',ARRAY['M3-2-u3-X12','M3-2-u3-X07']::text[],true,'{"seq":7,"concept":"M3-2-u3-C6","difficulty":1,"kind":"mc","stem":"컴퍼스로 원을 그리는 마지막 걸음은 무엇인가요?","options":[{"t":"침을 원의 중심에 꽂고 한 바퀴 돌려 그려요","correct":true},{"t":"원의 중심을 정해요","mis":"M3-2-u3-X12"},{"t":"컴퍼스를 반지름만큼 벌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"variant_rule":{"alt":[{"stem":"컴퍼스로 원을 그릴 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"원의 중심이 되는 점을 정해요","correct":true},{"t":"컴퍼스를 돌려요","mis":"M3-2-u3-X12"},{"t":"지름을 그어요","mis":"M3-2-u3-X07"},{"t":"침을 원 위에 꽂아요","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null},{"stem":"컴퍼스로 원을 그릴 때 침은 어디에 꽂나요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 한 점","mis":"M3-2-u3-X12"},{"t":"지름의 한 끝","mis":"M3-2-u3-X11"},{"t":"아무 곳이나","mis":"M3-2-u3-X12"}],"explanation":["① 원의 중심이 되는 점을 정해요.","② 침과 연필 끝을 반지름만큼 벌려요.","③ 침을 원의 중심에 꽂고 한 바퀴 돌려 그려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#8','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C7',1,'mc','auto','모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?',ARRAY['M3-2-u3-X14']::text[],true,'{"seq":8,"concept":"M3-2-u3-C7","difficulty":1,"kind":"mc","stem":"모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸, 2칸, 3칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 3, 1, 2칸.","규칙: 반지름이 1칸, 2칸, 3칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":300,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15],[[255,60],30]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"3칸, 2칸, 1칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸, 2칸이 되풀이돼요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 3, 2, 1, 3, 2칸.","규칙: 반지름이 3칸, 2칸, 1칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":360,"h":120,"grid":15,"circle":[[[60,60],45],[[135,60],30],[[180,60],15],[[240,60],45],[[315,60],30]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 원 무늬예요. 원의 반지름이 바뀌는 규칙은 무엇인가요?","options":[{"t":"1칸, 2칸이 되풀이돼요","correct":true},{"t":"모두 1칸이에요","mis":"M3-2-u3-X14"},{"t":"1칸씩 커져요","mis":"M3-2-u3-X14"},{"t":"2칸, 1칸이 되풀이돼요","mis":"M3-2-u3-X14"}],"explanation":["왼쪽 원부터 반지름을 모눈 칸으로 차례로 세어요.","반지름: 1, 2, 1, 2칸.","규칙: 반지름이 1칸, 2칸이 되풀이돼요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLU