INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#9','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C1',2,'mc','auto','원 위의 점은 어느 것인가요?',ARRAY['M3-2-u3-X02']::text[],true,'{"seq":9,"concept":"M3-2-u3-C1","difficulty":2,"kind":"mc","stem":"원 위의 점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄷ만 선 위에 있어요. 점 ㄱ은 원 안, 점 ㄴ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄷ":[24.8,72.8,"w"],"ㄱ":[68.4,45.4,"ne"],"ㄴ":[103.8,85.3,"se"]},"circle":[[[60,60],37.5]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원 위에 있는 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄷ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄴ만 선 위에 있어요. 점 ㄷ은 원 안, 점 ㄱ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄴ":[95.2,72.8,"e"],"ㄷ":[45.4,51.6,"nw"],"ㄱ":[42.7,107.6,"s"]},"circle":[[[60,60],37.5]]}],"tag":false}},{"stem":"원의 굽은 선 위에 놓인 점은 어느 것인가요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄴ","mis":"M3-2-u3-X02"},{"t":"점 ㄱ","mis":"M3-2-u3-X02"},{"t":"세 점 모두","mis":"M3-2-u3-X02"}],"explanation":["원은 굽은 선이에요 — 그 선 위에 있어야 원 위의 점이에요.","점 ㄹ만 선 위에 있어요. 점 ㄴ은 원 안, 점 ㄱ은 원 밖에 있어요.","원 안의 점은 원 위의 점이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㄹ":[60.0,22.5,"n"],"ㄴ":[49.2,72.9,"sw"],"ㄱ":[109.9,51.2,"e"]},"circle":[[[60,60],37.5]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconc