INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#10','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C2',2,'sa','auto','선분 ㅇㄱ의 길이는 7 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u3-C2","difficulty":2,"kind":"sa","stem":"선분 ㅇㄱ의 길이는 7 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 7 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"n"],"ㄱ":[24.8,72.8,"w"],"ㄴ":[88.7,84.1,"se"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[44.7,72.8],"7 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선분 ㅇㄱ의 길이는 8 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 8 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[35.9,88.7,"sw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[50.1,42.7],"8 cm"]]}],"tag":false}},{"stem":"선분 ㅇㄱ의 길이는 9 cm예요. 선분 ㅇㄴ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["점 ㅇ은 원의 중심, 점 ㄱ과 점 ㄴ은 원 위의 점이에요.","선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이에요.","한 원에서 반지름은 모두 같아요 — 9 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[95.2,72.8,"e"],"ㄴ":[41.2,27.5,"nw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"]],"lab":[[[79.9,60.1],"9 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#11','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',2,'mc','auto','지름을 그을 때 알맞은 방법은 어느 것인가요?',ARRAY['M3-2-u3-X06','M3-2-u3-X07','M3-2-u3-X02']::text[],true,'{"seq":11,"concept":"M3-2-u3-C3","difficulty":2,"kind":"mc","stem":"지름을 그을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"원의 중심에 자를 먼저 대고, 자와 원이 만나는 두 점을 이어요","correct":true},{"t":"원 위의 아무 두 점이나 이어요","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이어요","mis":"M3-2-u3-X07"},{"t":"원 밖의 두 점을 이어요","mis":"M3-2-u3-X02"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 지름을 그을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"원의 중심","correct":true},{"t":"원 위의 아무 점","mis":"M3-2-u3-X06"},{"t":"원 밖의 한 점","mis":"M3-2-u3-X02"},{"t":"원의 맨 위쪽 점","mis":"M3-2-u3-X06"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 지름을 그을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"원의 중심에 자를 먼저 대고, 자와 원이 만나는 두 점을 이어요","correct":true},{"t":"원 위의 아무 두 점이나 이어요","mis":"M3-2-u3-X06"},{"t":"원의 중심과 원 위의 한 점을 이어요","mis":"M3-2-u3-X07"},{"t":"원 밖의 두 점을 이어요","mis":"M3-2-u3-X02"}],"explanation":["지름은 원의 중심을 꼭 지나야 해요.","원의 중심에 자를 먼저 대고 자와 원이 만나는 두 점을 이으면 돼요.","아무 두 점이나 이으면 중심을 지나지 않을 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#12','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',2,'mc','auto','반지름이 1 cm, 2 cm인 두 원의 지름은 2 cm, 4 cm예요. 어떤 관계가 있나요?',ARRAY['M3-2-u3-X08','M3-2-u3-X09']::text[],true,'{"seq":12,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"반지름이 1 cm, 2 cm인 두 원의 지름은 2 cm, 4 cm예요. 어떤 관계가 있나요?","options":[{"t":"지름은 반지름의 2배예요","correct":true},{"t":"지름은 반지름의 반이에요","mis":"M3-2-u3-X08"},{"t":"지름은 반지름보다 1 cm 길어요","mis":"M3-2-u3-X09"},{"t":"지름과 반지름은 같아요","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「지름은 반지름의 2배예요」예요."],"variant_rule":{"alt":[{"stem":"한 원에서 지름과 반지름 사이의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지름은 반지름의 2배예요","correct":true},{"t":"반지름은 지름의 2배예요","mis":"M3-2-u3-X08"},{"t":"지름과 반지름은 길이가 같아요","mis":"M3-2-u3-X09"},{"t":"지름은 반지름보다 2 cm 길어요","mis":"M3-2-u3-X09"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「지름은 반지름의 2배예요」예요."],"asset":null},{"stem":"한 원에서 반지름은 지름의 얼마인가요?","options":[{"t":"반","correct":true},{"t":"2배","mis":"M3-2-u3-X08"},{"t":"같아요","mis":"M3-2-u3-X09"},{"t":"3배","mis":"M3-2-u3-X08"}],"explanation":["지름은 반지름 두 개를 이은 것과 같아요.","그래서 지름은 반지름의 2배, 반지름은 지름의 반이에요.","답은 「반」이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#13','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C5',2,'mc','auto','가장 큰 원은 어느 것인가요? (㉠ 반지름 5 cm, ㉡ 반지름 6 cm, ㉢ 지름 11 cm)',ARRAY['M3-2-u3-X16','M3-2-u3-X10']::text[],true,'{"seq":13,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"가장 큰 원은 어느 것인가요? (㉠ 반지름 5 cm, ㉡ 반지름 6 cm, ㉢ 지름 11 cm)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X16"},{"t":"㉢","mis":"M3-2-u3-X10"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 10 cm, ㉡ 지름 12 cm, ㉢ 지름 11 cm.","가장 큰 원은 ㉡이에요."],"variant_rule":{"alt":[{"stem":"가장 큰 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X16"},{"t":"㉢","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 8 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm.","가장 큰 원은 ㉡이에요."],"asset":null},{"stem":"가장 큰 원은 어느 것인가요? (㉠ 지름 6 cm, ㉡ 반지름 4 cm, ㉢ 반지름 2 cm)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 8 cm, ㉢ 지름 4 cm.","가장 큰 원은 ㉡이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#14','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C6',2,'sa','auto','컴퍼스로 지름이 14 cm인 원을 그려요. 침과 연필 끝 사이를 몇 cm로 해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"컴퍼스로 지름이 14 cm인 원을 그려요. 침과 연필 끝 사이를 몇 cm로 해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 14 cm의 반 — 반지름은 7 cm예요.","7 cm 벌려요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원을 그리려면 컴퍼스를 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 4 cm의 반 — 반지름은 2 cm예요.","2 cm 벌려요."],"asset":null},{"stem":"지름 8 cm인 원 모양 무늬를 컴퍼스로 그리려고 해요. 몇 cm 벌려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["컴퍼스는 언제나 반지름만큼 벌려요.","지름 8 cm의 반 — 반지름은 4 cm예요.","4 cm 벌려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#15','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C7',2,'sa','auto','이 규칙대로 원을 계속 그리면 여덟째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"이 규칙대로 원을 계속 그리면 여덟째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 2칸, 1칸이 되풀이돼요.","차례로 이어 쓰면 2, 1, 2, 1, 2, 1, 2, 1칸.","여덟째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 규칙대로 원을 계속 그리면 다섯째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 1칸, 2칸이 되풀이돼요.","차례로 이어 쓰면 1, 2, 1, 2, 1칸.","다섯째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}},{"stem":"이 규칙대로 원을 계속 그리면 일곱째 원의 반지름은 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["반지름 규칙: 1칸, 2칸, 3칸이 되풀이돼요.","차례로 이어 쓰면 1, 2, 3, 1, 2, 3, 1칸.","일곱째 원은 1칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#16','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C4',2,'sa','auto','점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M3-2-u3-C4","difficulty":2,"kind":"sa","stem":"점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["선분 ㅇㄱ은 반지름 — 3 cm예요.","지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"w"],"ㄱ":[96.6,46.7,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[76.0,47.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㅇㄱ은 반지름 — 4 cm예요.","지름은 반지름의 2배예요.","4 × 2 = 8(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[46.7,23.4,"n"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[47.0,44.0],"4 cm"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 점 ㅇ은 원의 중심이에요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["선분 ㅇㄱ은 반지름 — 5 cm예요.","지름은 반지름의 2배예요.","5 × 2 = 10(cm)예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[23.4,73.3,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㅇ","ㄱ"]],"lab":[[[44.0,73.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#17','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C2',3,'error','auto','원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u3-X03','M3-2-u3-X16']::text[],true,'{"seq":17,"concept":"M3-2-u3-C2","difficulty":3,"kind":"error","stem":"원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「원의 중심은 원 위에 있어.」","correct":true,"mis_target":"M3-2-u3-X03"},{"t":"가람 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"하늘 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"},{"t":"도윤 — 「원은 꼭짓점이 없어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","민호의 말 「원의 중심은 원 위에 있어」가 잘못이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"가람 — 「반지름은 그은 자리마다 길이가 달라.」","correct":true,"mis_target":"M3-2-u3-X05"},{"t":"하늘 — 「원의 중심은 한 원에 하나야.」","mis":"M3-2-u3-X16"},{"t":"도윤 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"},{"t":"나래 — 「원은 꼭짓점이 없어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","가람의 말 「반지름은 그은 자리마다 길이가 달라」가 잘못이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 원의 중심과 반지름에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「원 안에 있는 점도 원 위의 점이야.」","correct":true,"mis_target":"M3-2-u3-X02"},{"t":"도윤 — 「원의 중심은 한 원에 하나야.」","mis":"M3-2-u3-X16"},{"t":"나래 — 「한 원에서 반지름은 모두 같아.」","mis":"M3-2-u3-X16"},{"t":"서윤 — 「반지름은 원의 중심과 원 위의 한 점을 이어.」","mis":"M3-2-u3-X16"}],"explanation":["원의 중심은 원의 가장 안쪽 한 점(한 원에 하나)이에요.","반지름은 원 위의 점마다 그을 수 있어 셀 수 없이 많고, 길이가 모두 같아요.","하늘의 말 「원 안에 있는 점도 원 위의 점이야」가 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_c#18','math',3,2,'u3','','g3_2_math_u3_review_c','unit_review','M3-2-u3-C3',3,'sa','auto','그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-2-u3-C3","difficulty":3,"kind":"sa","stem":"그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 2개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"se"],"ㄱ":[93.8,40.5,"ne"],"ㄴ":[26.2,79.5,"sw"],"ㄷ":[60.0,21.0,"n"],"ㄹ":[60.0,99.0,"s"],"ㅁ":[34.9,30.1,"nw"],"ㅂ":[21.0,60.0,"w"],"ㅅ":[79.5,93.8,"se"],"ㅈ":[98.4,66.8,"e"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅅ","ㅈ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"sw"],"ㄱ":[98.4,53.2,"e"],"ㄴ":[21.6,66.8,"w"],"ㄷ":[73.3,23.4,"n"],"ㄹ":[46.7,96.6,"s"],"ㅁ":[34.9,30.1,"nw"],"ㅂ":[85.1,89.9,"se"],"ㅅ":[23.4,46.7,"w"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 지름은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["원 위의 두 점을 이으면서 원의 중심 ㅇ을 지나는 선분만 지름이에요.","중심을 지나지 않는 선분과 중심에서 시작하는 반지름은 빼요.","지름은 1개예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[66.8,21.6,"n"],"ㄴ":[53.2,98.4,"s"],"ㄷ":[99.0,60.0,"e"],"ㄹ":[40.5,26.2,"nw"],"ㅁ":[21.6,66.8,"w"],"ㅂ":[79.5,93.8,"se"],"ㅅ":[30.1,34.9,"nw"]},"circle":[[[60,60],39.0]],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"],["ㅇ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=E