INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#12','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C4',2,'mc','auto','카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M3-2-u3-X09','M3-2-u3-X08']::text[],true,'{"seq":12,"concept":"M3-2-u3-C4","difficulty":2,"kind":"mc","stem":"카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 5 cm · 지름 10 cm","correct":true},{"t":"반지름 6 cm · 지름 6 cm","mis":"M3-2-u3-X09"},{"t":"반지름 10 cm · 지름 5 cm","mis":"M3-2-u3-X08"},{"t":"반지름 4 cm · 지름 16 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 5 cm인 원의 지름은 10 cm예요.","반지름 5 cm · 지름 10 cm가 같은 원이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 6 cm · 지름 12 cm","correct":true},{"t":"반지름 7 cm · 지름 7 cm","mis":"M3-2-u3-X09"},{"t":"반지름 12 cm · 지름 6 cm","mis":"M3-2-u3-X08"},{"t":"반지름 5 cm · 지름 20 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 6 cm인 원의 지름은 12 cm예요.","반지름 6 cm · 지름 12 cm가 같은 원이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 카드 뒤집기 놀이를 해요. 반지름(지름)이 같은 원끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"반지름 3 cm · 지름 6 cm","correct":true},{"t":"반지름 4 cm · 지름 4 cm","mis":"M3-2-u3-X09"},{"t":"반지름 6 cm · 지름 3 cm","mis":"M3-2-u3-X08"},{"t":"반지름 2 cm · 지름 8 cm","mis":"M3-2-u3-X08"}],"explanation":["반지름의 2배가 지름이에요.","반지름 3 cm인 원의 지름은 6 cm예요.","반지름 3 cm · 지름 6 cm가 같은 원이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#13','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C5',2,'mc','auto','가장 작은 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)',ARRAY['M3-2-u3-X10','M3-2-u3-X16']::text[],true,'{"seq":13,"concept":"M3-2-u3-C5","difficulty":2,"kind":"mc","stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 4 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 8 cm, ㉡ 지름 9 cm, ㉢ 지름 7 cm.","가장 작은 원은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"가장 작은 원은 어느 것인가요? (㉠ 지름 6 cm, ㉡ 반지름 4 cm, ㉢ 반지름 2 cm)","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u3-X16"},{"t":"㉡","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 8 cm, ㉢ 지름 4 cm.","가장 작은 원은 ㉢이에요."],"asset":null},{"stem":"가장 작은 원은 어느 것인가요? (㉠ 반지름 3 cm, ㉡ 지름 5 cm, ㉢ 지름 8 cm)","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M3-2-u3-X10"},{"t":"㉢","mis":"M3-2-u3-X16"},{"t":"모두 같아요","mis":"M3-2-u3-X10"}],"explanation":["반지름과 지름이 섞여 있으면 모두 지름으로 바꾸어 견줘요.","㉠ 지름 6 cm, ㉡ 지름 5 cm, ㉢ 지름 8 cm.","가장 작은 원은 ㉡이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#14','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',2,'sa','auto','컴퍼스를 1 cm 벌려 그린 원의 지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M3-2-u3-C6","difficulty":2,"kind":"sa","stem":"컴퍼스를 1 cm 벌려 그린 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["벌린 길이 1 cm가 반지름이에요.","지름은 반지름의 2배예요.","1 × 2 = 2(cm)예요."],"variant_rule":{"alt":[{"stem":"컴퍼스의 침과 연필 끝 사이를 3 cm로 하고 원을 그렸어요. 이 원의 지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["벌린 길이 3 cm가 반지름이에요.","지름은 반지름의 2배예요.","3 × 2 = 6(cm)예요."],"asset":null},{"stem":"4 cm 벌린 컴퍼스로 그린 원에 지름을 그으면 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["벌린 길이 4 cm가 반지름이에요.","지름은 반지름의 2배예요.","4 × 2 = 8(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#15','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',2,'sa','auto','원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M3-2-u3-C7","difficulty":2,"kind":"sa","stem":"원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["2"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","2칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"grid":15,"circle":[[[30,30],15],[[60,30],15],[[90,30],15],[[120,30],15]],"pts":{"①":[30,30,"n"],"②":[60,30,"n"],"③":[90,30,"n"],"④":[120,30,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["3"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","3칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":195,"h":60,"grid":15,"circle":[[[30,30],15],[[75,30],15],[[120,30],15],[[165,30],15]],"pts":{"①":[30,30,"n"],"②":[75,30,"n"],"③":[120,30,"n"],"④":[165,30,"n"]}}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 원의 중심(①, ②, ③…)을 오른쪽으로 모눈 몇 칸씩 옮겨 그렸나요? 숫자로 쓰세요.","answer":["3"],"explanation":["①과 ②의 중심 사이 칸을 세어요.","②와 ③ 사이도 같아요.","3칸씩 옮겼어요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]],"pts":{"①":[30,45,"n"],"②":[75,45,"n"],"③":[120,45,"n"],"④":[165,45,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
