INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#17','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C2',3,'ox','auto','원의 중심은 원 위에 있어요.',ARRAY['M3-2-u3-X03']::text[],true,'{"seq":17,"concept":"M3-2-u3-C2","difficulty":3,"kind":"ox","stem":"원의 중심은 원 위에 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"mis":"M3-2-u3-X03","explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"variant_rule":{"alt":[{"stem":"한 원에 원의 중심은 여러 개 있어요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null},{"stem":"누름 못이 꽂힌 점은 원 위의 점이에요.","answer":"X","reason_options":[{"t":"원의 중심은 원의 가장 안쪽 한 점이라서","correct":true},{"t":"원의 중심도 원의 굽은 선 위에 있어서","mis":"M3-2-u3-X03"}],"explanation":["원의 중심은 원 위가 아니라 원의 가장 안쪽에 있어요.","한 원에 원의 중심은 하나뿐이에요.","이 말은 틀렸어요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
