INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#19','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C5',3,'ox','auto','지름이 6 cm인 원은 반지름이 6 cm인 원과 크기가 같아요.',ARRAY['M3-2-u3-X10']::text[],true,'{"seq":19,"concept":"M3-2-u3-C5","difficulty":3,"kind":"ox","stem":"지름이 6 cm인 원은 반지름이 6 cm인 원과 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 6 cm인 원은 지름이 12 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"mis":"M3-2-u3-X10","explanation":["반지름 6 cm인 원의 지름은 12 cm예요.","지름 6 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"variant_rule":{"alt":[{"stem":"반지름 8 cm인 원과 지름 8 cm인 원 가운데 어느 원도 더 크지 않아요.","answer":"X","reason_options":[{"t":"반지름 8 cm인 원은 지름이 16 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 8 cm인 원의 지름은 16 cm예요.","지름 8 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null},{"stem":"반지름이 4 cm인 원과 지름이 4 cm인 원은 크기가 같아요.","answer":"X","reason_options":[{"t":"반지름 4 cm인 원은 지름이 8 cm라서","correct":true},{"t":"수가 같으면 원의 크기도 같아서","mis":"M3-2-u3-X10"}],"explanation":["반지름 4 cm인 원의 지름은 8 cm예요.","지름 4 cm인 원보다 커요.","그래서 크기가 같지 않아요(X)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#20','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C8',3,'sa','auto','반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-2-u3-C8","difficulty":3,"kind":"sa","stem":"반지름이 3 cm인 원 4개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직사각형의 가로에는 원의 지름이 4개, 세로에는 1개 들어 있어요.","지름은 3 × 2 = 6(cm).","6 × 4 = 24(cm)예요."],"asset":{"type":"geo","items":[{"w":138.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0],[[114.0,24.0],15.0]],"seg":[[[9.0,9.0],[129.0,9.0]],[[129.0,9.0],[129.0,39.0]],[[129.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원 3개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["직사각형의 가로에는 원의 지름이 3개, 세로에는 1개 들어 있어요.","지름은 4 × 2 = 8(cm).","세로는 지름 하나 — 8 cm예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"seg":[[[9.0,9.0],[99.0,9.0]],[[99.0,9.0],[99.0,39.0]],[[99.0,39.0],[9.0,39.0]],[[9.0,39.0],[9.0,9.0]]]}],"tag":false}},{"stem":"반지름이 2 cm인 원 5개를 맞닿게 한 줄로 그리고, 꼭 맞는 직사각형으로 둘러쌌어요. 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["직사각형의 가로에는 원의 지름이 5개, 세로에는 1개 들어 있어요.","지름은 2 × 2 = 4(cm).","4 × 5 = 20(cm)예요."],"asset":{"type":"geo","items":[{"w":145.5,"h":43.5,"circle":[[[21.8,21.8],12.8],[[47.2,21.8],12.8],[[72.8,21.8],12.8],[[98.2,21.8],12.8],[[123.8,21.8],12.8]],"seg":[[[9.0,9.0],[136.5,9.0]],[[136.5,9.0],[136.5,34.5]],[[136.5,34.5],[9.0,34.5]],[[9.0,34.5],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED