INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#21','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C6',3,'mc','auto','지름이 4 cm인 원을 그리려고 컴퍼스를 4 cm 벌려 그렸어요. 어떤 원이 그려지나요?',ARRAY['M3-2-u3-X11','M3-2-u3-X08','M3-2-u3-X12']::text[],true,'{"seq":21,"concept":"M3-2-u3-C6","difficulty":3,"kind":"mc","stem":"지름이 4 cm인 원을 그리려고 컴퍼스를 4 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 8 cm인 원","correct":true},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 2 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 4 cm는 반지름이 돼요.","지름은 반지름의 2배 — 8 cm예요.","지름 4 cm인 원을 그리려면 2 cm만 벌려야 해요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원을 그리려고 컴퍼스를 6 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 12 cm인 원","correct":true},{"t":"지름이 6 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 3 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 6 cm는 반지름이 돼요.","지름은 반지름의 2배 — 12 cm예요.","지름 6 cm인 원을 그리려면 3 cm만 벌려야 해요."],"asset":null},{"stem":"지름이 8 cm인 원을 그리려고 컴퍼스를 8 cm 벌려 그렸어요. 어떤 원이 그려지나요?","options":[{"t":"지름이 16 cm인 원","correct":true},{"t":"지름이 8 cm인 원","mis":"M3-2-u3-X11"},{"t":"지름이 4 cm인 원","mis":"M3-2-u3-X08"},{"t":"원이 그려지지 않아요","mis":"M3-2-u3-X12"}],"explanation":["벌린 8 cm는 반지름이 돼요.","지름은 반지름의 2배 — 16 cm예요.","지름 8 cm인 원을 그리려면 4 cm만 벌려야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#22','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C7',3,'sa','auto','원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 셋째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M3-2-u3-C7","difficulty":3,"kind":"sa","stem":"원이 맞닿게 이어진 무늬예요. 첫째 원의 중심에서 셋째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["첫째 원은 반지름, 사이의 원은 지름, 셋째 원은 반지름만큼 들어 있어요.","1 + 4 + 3칸.","모두 8칸이에요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":15,"circle":[[[30,60],15],[[75,60],30],[[150,60],45],[[210,60],15]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원이 맞닿게 이어진 무늬예요. 둘째 원의 중심에서 다섯째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["둘째 원은 반지름, 사이의 원은 지름, 다섯째 원은 반지름만큼 들어 있어요.","1 + 4 + 2 + 2칸.","모두 9칸이에요."],"asset":{"type":"geo","items":[{"w":270,"h":90,"grid":15,"circle":[[[45,45],30],[[90,45],15],[[135,45],30],[[180,45],15],[[225,45],30]]}],"tag":false}},{"stem":"원이 맞닿게 이어진 무늬예요. 둘째 원의 중심에서 넷째 원의 중심까지는 모눈 몇 칸인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["둘째 원은 반지름, 사이의 원은 지름, 넷째 원은 반지름만큼 들어 있어요.","2 + 2 + 2칸.","모두 6칸이에요."],"asset":{"type":"geo","items":[{"w":210,"h":90,"grid":15,"circle":[[[30,45],15],[[75,45],30],[[120,45],15],[[165,45],30]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#23','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C8',4,'sa','auto','직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 12 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-2-u3-C8","difficulty":4,"kind":"sa","stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 12 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["가로에는 원의 지름이 2개 들어 있어요.","지름: 12의 반 = 6(cm).","반지름: 6의 반 = 3(cm)예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 16 cm일 때 세로는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["가로에는 원의 지름이 2개, 세로에는 1개 들어 있어요.","지름 하나: 16의 반 = 8(cm).","세로는 지름 하나 — 8 cm예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}},{"stem":"직사각형 안에 크기가 같은 원 2개가 맞닿게 꼭 맞게 들어 있어요. 직사각형의 가로가 20 cm일 때 원 하나의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가로에는 원의 지름이 2개 들어 있어요.","지름: 20의 반 = 10(cm).","반지름: 10의 반 = 5(cm)예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":57.0,"circle":[[[28.5,28.5],19.5],[[67.5,28.5],19.5]],"seg":[[[9.0,9.0],[87.0,9.0]],[[87.0,9.0],[87.0,48.0]],[[87.0,48.0],[9.0,48.0]],[[9.0,48.0],[9.0,9.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#24','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C3',4,'sa','auto','원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 4 cm이고 삼각형의 세 변의 길이의 합은 10 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-2-u3-C3","difficulty":4,"kind":"sa","stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 4 cm이고 삼각형의 세 변의 길이의 합은 10 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 10 − 4 = 6(cm).","반지름 하나는 6의 반 — 3 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"s"],"ㄱ":[95.2,47.2,"e"],"ㄴ":[31.3,35.9,"nw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 10 cm이고 삼각형의 세 변의 길이의 합은 26 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 26 − 10 = 16(cm).","반지름 하나는 16의 반 — 8 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"n"],"ㄱ":[24.8,72.8,"w"],"ㄴ":[88.7,84.1,"se"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}},{"stem":"원의 중심 ㅇ과 원 위의 두 점 ㄱ, ㄴ을 이어 삼각형을 만들었어요. 선분 ㄱㄴ은 6 cm이고 삼각형의 세 변의 길이의 합은 16 cm예요. 이 원의 반지름은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["선분 ㅇㄱ과 선분 ㅇㄴ은 모두 반지름이라 길이가 같아요.","두 반지름의 합: 16 − 6 = 10(cm).","반지름 하나는 10의 반 — 5 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"pts":{"ㅇ":[60,60,"e"],"ㄱ":[53.5,23.1,"n"],"ㄴ":[31.3,84.1,"sw"]},"circle":[[[60,60],37.5]],"seg":[["ㅇ","ㄱ"],["ㅇ","ㄴ"],["ㄱ","ㄴ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_math_u3_review_d#25','math',3,2,'u3','','g3_2_math_u3_review_d','unit_review','M3-2-u3-C8',4,'essay','teacher','반지름이 3 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심에서 셋째 원의 중심까지의 길이를 구하는 방법을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u3-C8","difficulty":4,"kind":"essay","stem":"반지름이 3 cm인 원 3개를 맞닿게 한 줄로 그렸어요. 첫째 원의 중심에서 셋째 원의 중심까지의 길이를 구하는 방법을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 첫째 원의 중심에서 셋째 원의 중심까지 선분을 그으면 첫째 원의 반지름, 둘째 원의 지름, 셋째 원의 반지름이 들어 있다. 반지름 4개와 같으므로 3 × 4 = 12(cm)이다.","scoring_points":["선분 위에 반지름·지름이 몇 개 있는지 찾았는가","반지름 4개(지름 2개)라고 썼는가","12 cm를 구했는가"]},"explanation":["선분 위의 반지름을 하나씩 세어요.","반지름 + 지름 + 반지름 = 반지름 4개.","3 × 4 = 12(cm)."],"asset":{"type":"geo","items":[{"w":108.0,"h":48.0,"circle":[[[24.0,24.0],15.0],[[54.0,24.0],15.0],[[84.0,24.0],15.0]],"pts":{"ㄱ":[24.0,24.0,"s"],"ㄴ":[84.0,24.0,"s"]},"seg":[["ㄱ","ㄴ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
